public static class Research
{
    private static List<Verse> GetSourceVerses(Client client, bool in_search_result)
    {
        List<Verse> verses = null;
        if (client != null)
        {
            switch (client.SearchScope)
            {
                case SearchScope.Book:
                    {
                        if (client.Book != null)
                        {
                            verses = client.Book.Verses;
                        }
                    }
                    break;
                case SearchScope.Selection:
                    {
                        if (client.Selection != null)
                        {
                            verses = client.Selection.Verses;
                        }
                    }
                    break;
                case SearchScope.Result:
                    {
                        verses = in_search_result ? client.FoundVerses : client.Selection.Verses;
                    }
                    break;
            }
        }
        return verses;
    }

    private static string _____________________________001(Client client, string param, bool in_search_result)
    {
        return null;
    }
    private static string ChapterVerses_PAP(Client client, string param, bool in_search_result)
    {
        StringBuilder str = new StringBuilder();
        str.AppendLine("--------------------------------------------------------------------------------");
        str.AppendLine("P|AP" + "\t" + "Name" + "\t" + "Chapter" + "\t" + "Verses");
        str.AppendLine("--------------------------------------------------------------------------------");

        int count = 0;
        int max = Math.Min(Numbers.Primes.Count, Numbers.AdditivePrimes.Count);
        for (int i = 0; i < max; i++)
        {
            long P = Numbers.Primes[i];
            long AP = Numbers.AdditivePrimes[i];
            if ((P >= 1) && (AP >= 1))
            {
                count++;
                foreach (Chapter chapter in client.Book.Chapters)
                {
                    if ((chapter.SortedNumber == P) && (chapter.Verses.Count == AP))
                    {
                        str.AppendLine(count + "\t" + chapter.Name + "\t" + P + "\t" + AP);
                    }
                }
            }
        }
        return str.ToString();
    }
