        str.AppendLine("--------------------------------------------------------------------------------");
        str.AppendLine("#" + "\t" + "P" + "\t" + "iP" + "\t" + "C" + "\t" + "iC" + "\t" + "Chapter" + "\t" + "Verses");
        str.AppendLine("--------------------------------------------------------------------------------");

        int count = 0;
        for (int i = 0; i < Numbers.Primes.Count; i++)
        {
            long P = Numbers.Primes[i];         // P = 59   iP = 17
            long C = Numbers.Composites[i];     // C = 27   iC = 17
            long iP = i + 1;                    // i + 1       = 17 Verses or Chapter
            long iC = i + 1;                    // i + 1       = 17 Verses or Chapter
            long sum = P + C;                   // sum = 59+27 = 86 Chapter or Verses
            if ((P >= 1) && (C >= 1))
            {
                count++;
                foreach (Chapter chapter in client.Book.Chapters)
                {
                    if ((chapter.SortedNumber == iP) && (chapter.Verses.Count == sum))
                    {
                        str.AppendLine("#" + "\t" + P + "\t" + iP + "\t" + C + "\t" + iC + "\t" + iP + "\t" + sum);
                    }
                }
            }
        }
        return str.ToString();
    }
