    private static string OWords_EQ_OLetters(Client client, string param, bool in_search_result)
    {
        if (client == null) return null;
        if (client.Book == null) return null;
        if (client.Book.Chapters == null) return null;

        StringBuilder str = new StringBuilder();
        str.AppendLine("--------------------------------------------");
        str.AppendLine("#" + "\t" + "Chapter" + "\t" + "Name" + "\t" + "OWords" + "\t" + "OLetters");
        str.AppendLine("--------------------------------------------");

        foreach (NumericalSystem ns in client.LoadedNumericalSystems.Values)
        {
            if (ns != null)
            {
                if (ns.TextMode == client.NumericalSystem.TextMode)
                {
                    if (ns.Name.EndsWith("Zeros")) continue;
                    if (ns.Name.Contains("English")) continue;

                    bool ns_displayed = false;

                    int count = 0;
                    foreach (Chapter chapter in client.Book.Chapters)
                    {
                        long words_value_sum = 0L;
                        foreach (Word word in chapter.Words)
                        {
                            if (Numbers.IsOdd(word.NumberInChapter))
                            {
                                words_value_sum += ns.CalculateValue(word.Text.Simplify(ns.TextMode));
                            }
                        }

                        long letters_value_sum = 0L;
                        foreach (Letter letter in chapter.Letters)
                        {
                            if (Numbers.IsOdd(letter.NumberInChapter))
                            {
                                letters_value_sum += ns.CalculateValue(letter.Character);
                            }
                        }

                        if (words_value_sum == letters_value_sum)
                        {
                            if (!ns_displayed)
                            {
                                str.AppendLine(ns.Name);
                                ns_displayed = true;
                            }
                            str.AppendLine(++count + "\t" + chapter.SortedNumber.ToString() + "\t" + chapter.Name + "\t" + words_value_sum + "\t" + letters_value_sum);
                        }
                    }
                }
            }
        }

        return str.ToString();
    }
