    private static string OWords_Minus_OValues_EQ_LastWord(Client client, string param, bool in_search_result)
    {
        if (client == null) return null;
        if (client.Book == null) return null;
        if (client.Book.Chapters == null) return null;

        StringBuilder str = new StringBuilder();
        str.AppendLine("---------------------------------------------------------------------");
        str.AppendLine("#" + "\t" + "Chapter" + "\t" + "Name" + "\t" + "OWords" + "\t" + "OValues" + "\t" + "Diff" + "\t" + "LastWord" + "\t" + "Value");
        str.AppendLine("---------------------------------------------------------------------");

        foreach (NumericalSystem ns in client.LoadedNumericalSystems.Values)
        {
            if (ns != null)
            {
                if (ns.TextMode == client.NumericalSystem.TextMode)
                {
                    if (ns.Name.EndsWith("Zeros")) continue;
                    if (ns.Name.Contains("English")) continue;

                    bool ns_displayed = false;

                    int count = 0;
                    foreach (Chapter chapter in client.Book.Chapters)
                    {
                        long value_sum_1 = 0L;
                        foreach (Word word in chapter.Words)
                        {
                            if (Numbers.IsOdd(word.NumberInChapter))
                            {
                                value_sum_1 += ns.CalculateValue(word.Text.Simplify(ns.TextMode));
                            }
                        }
                        long value_sum_2 = 0L;
                        foreach (Word word in chapter.Words)
                        {
                            long value = ns.CalculateValue(word.Text.Simplify(ns.TextMode));
                            if (Numbers.IsOdd(value))
                            {
                                value_sum_2 += value;
                            }
                        }
                        long value_diff = (long)Math.Abs(value_sum_1 - value_sum_2);

                        string last_word = chapter.Words[chapter.Words.Count - 1].Text;
                        long last_value = ns.CalculateValue(last_word.Simplify(ns.TextMode));
                        if (last_value == value_diff)
                        {
                            if (!ns_displayed)
                            {
                                str.AppendLine(ns.Name);
                                ns_displayed = true;
                            }
                            str.AppendLine(++count + "\t" + chapter.SortedNumber.ToString() + "\t" + chapter.Name + "\t" + value_sum_1 + "\t" + value_sum_2 + "\t" + value_diff + "\t" + last_word + "\t" + last_value);
                        }
                    }
                }
            }
        }

        return str.ToString();
    }
