    private static string P_AP_for_iP_EQ_iC(Client client, string param, bool in_search_result)
    {
        StringBuilder str = new StringBuilder();
        str.AppendLine("------------------------------------------------------");
        str.AppendLine("#" + "\t" + "n" + "\t" + "Pn" + "\t" + "APn" + "\t" + "XPn" + "\t" + "P(Pn)" + "\t" + "C(APn)");
        str.AppendLine("------------------------------------------------------");

        try
        {
            int count = 0;
            foreach (long number in Numbers.Primes)                         // Find cases similar to
            {                                                               // 46 = C31 = AC20
                int p = Numbers.PrimeIndexOf(number) + 1;                   // 31 = P11
                int ap = Numbers.AdditivePrimeIndexOf(number) + 1;          // 20 = C11
                int xp = Numbers.NonAdditivePrimeIndexOf(number) + 1;       //  0

                int Pp = 0;
                int APp = 0;
                int XPp = 0;
                int Cap = 0;
                int ACap = 0;
                int XCap = 0;
                if (Numbers.IsPrime(p))
                {
                    Pp = Numbers.PrimeIndexOf(p) + 1;                       // 11
                    APp = Numbers.AdditivePrimeIndexOf(p) + 1;              //  0
                    XPp = Numbers.NonAdditivePrimeIndexOf(p) + 1;           //  4
                }
                if (Numbers.IsComposite(ap))
                {
                    Cap = Numbers.CompositeIndexOf(ap) + 1;                 // 11
                    ACap = Numbers.AdditiveCompositeIndexOf(ap) + 1;        //  0
                    XCap = Numbers.NonAdditiveCompositeIndexOf(ap) + 1;     //  5
                }
                if ((Pp > 0) && (Cap > 0))
                {
                    if (Pp == Cap)
                    {
                        count++;
                        str.AppendLine(count + "\t" + number + "\t" + p + "\t" + ap + "\t" + xp + "\t" + Pp + "\t" + Cap);
                    }
                }
            }
        }
        catch (Exception ex)
        {
            return ex.InnerException.ToString();
        }

        return str.ToString();
    }
