    private static string CalculateBookSymmetry(Client client, List<Chapter> chapters)
    {
        if (client == null)
            return null;
        if (chapters == null)
            return null;

        StringBuilder str = new StringBuilder();

        str.AppendLine("Chapter" + "\t" + "Number" + "\t" + "Verses" + "\t" + "Sum" + "\t" + "Odd" + "\t" + "Even");

        //          c   c+v
        Dictionary<int, int> sums = new Dictionary<int, int>();
        Dictionary<int, int> odd_sums = new Dictionary<int, int>();
        Dictionary<int, int> even_sums = new Dictionary<int, int>();
        long c_total = 0L;
        long v_total = 0L;
        long sums_total = 0L;
        long odd_sums_total = 0L;
        long even_sums_total = 0L;
        int odd_sums_count = 0;
        int even_sums_count = 0;
        foreach (Chapter chapter in chapters)
        {
            int c = chapter.SortedNumber;
            int v = chapter.Verses.Count;
            int sum = c + v;
            c_total += c;
            v_total += v;
            sums_total += sum;

            sums.Add(c, sum);
            if ((sum % 2) == 1) // odd sum
            {
                odd_sums.Add(c, sum);
                even_sums.Add(c, 0);

                odd_sums_total += sum;
                odd_sums_count++;
            }
            else // even sum
            {
                odd_sums.Add(c, 0);
                even_sums.Add(c, sum);

                even_sums_total += sum;
                even_sums_count++;
            }
        }

        foreach (Chapter chapter in chapters)
        {
            string name = chapter.Name;
            int c = chapter.SortedNumber;
            int v = chapter.Verses.Count;
            str.AppendLine(name + "\t" + c + "\t" + v + "\t" + sums[c] + "\t"
                + ((odd_sums[c] > 0) ? odd_sums[c].ToString() : "") + "\t"
                + ((even_sums[c] > 0) ? even_sums[c].ToString() : "")
            );
        }
        str.AppendLine("Count" + "\t" + chapters.Count + "\t" + chapters.Count + "\t" + chapters.Count + "\t" + odd_sums_count + "\t" + even_sums_count);
        str.AppendLine("Sum" + "\t" + c_total + "\t" + v_total + "\t" + sums_total + "\t" + odd_sums_total + "\t" + even_sums_total);
        str.AppendLine();

        double symmetry = 0.0D;
        if (odd_sums_count == even_sums_count)
        {
            str.AppendLine("Odd Sums Count = Even Sums Count = " + odd_sums_count.ToString());
            symmetry += 0.25D;
        }

        if (c_total == odd_sums_total)
        {
            str.AppendLine("Chapter Numbers Sum = Odd Sums Count = " + odd_sums_total.ToString());
            symmetry += 0.25D;
        }
        else if (c_total == even_sums_total)
        {
            str.AppendLine("Chapter Numbers Sum = Even Sums Count = " + even_sums_total.ToString());
            symmetry += 0.25D;
        }

        if (v_total == odd_sums_total)
        {
            str.AppendLine("Chapter Verses Sum = Odd Sums Count = " + odd_sums_total.ToString());
            symmetry += 0.25D;
        }
        else if (v_total == even_sums_total)
        {
            str.AppendLine("Chapter Verses Sum = Even Sums Count = " + even_sums_total.ToString());
            symmetry += 0.25D;
        }

        foreach (int number in Numbers.InterestingNumbers)
        {
            if (sums_total == number)
            {
                str.AppendLine();
                str.AppendLine("Sums Total " + sums_total + " is the 786th non-additive prime where");
                str.AppendLine("786 is the Abjad_Gematria value of بسـم اللـه الرحمـن الرحيـم");
                symmetry += 0.25D;
            }
        }

        str.AppendLine();
        str.AppendLine("Symmetry = " + symmetry * 100.0D + "%");

        return str.ToString();
    }
    private static string CalculateBookGoldenRatio(Client client, List<Chapter> chapters)
    {
        if (client == null)
            return null;
        if (chapters == null)
            return null;

        StringBuilder str = new StringBuilder();

        str.AppendLine("Chapter" + "\t" + "Number" + "\t" + "Verses" + "\t" + "Sum" + "\t" + "Repeat" + "\t" + "Unique");

        //         sum  freq
        Dictionary<int, int> sums_frequencies = new Dictionary<int, int>();
        long c_total = 0L;
        long v_total = 0L;
        long sums_total = 0L;
        long repeated_sums_total = 0L;
        long unique_sums_total = 0L;
        int repeated_sums_count = 0;
        int unique_sums_count = 0;
        foreach (Chapter chapter in chapters)
        {
            int c = chapter.SortedNumber;
            int v = chapter.Verses.Count;
            int sum = c + v;
            c_total += c;
            v_total += v;
            sums_total += sum;

            if (sums_frequencies.ContainsKey(sum))
            {
                sums_frequencies[sum]++;
            }
            else
            {
                sums_frequencies.Add(sum, 1);
            }
        }

        foreach (Chapter chapter in chapters)
        {
            int c = chapter.SortedNumber;
            int v = chapter.Verses.Count;
            int sum = c + v;

            if (sums_frequencies[sum] > 1) // repeated sum
            {
                repeated_sums_total += sum;
                repeated_sums_count++;
            }
            else // unique sum
            {
                unique_sums_total += sum;
                unique_sums_count++;
            }
        }

        foreach (Chapter chapter in chapters)
        {
            string name = chapter.Name;
            int c = chapter.SortedNumber;
            int v = chapter.Verses.Count;
            str.AppendLine(name + "\t" + c + "\t" + v + "\t" + (c + v) + "\t"
                + ((sums_frequencies[c + v] > 1) ? (c + v).ToString() : "") + "\t"
                + ((sums_frequencies[c + v] == 1) ? (c + v).ToString() : "")
            );
        }
        str.AppendLine("Count" + "\t" + chapters.Count + "\t" + chapters.Count + "\t" + chapters.Count + "\t" + repeated_sums_count + "\t" + unique_sums_count);
        str.AppendLine("Sum" + "\t" + c_total + "\t" + v_total + "\t" + sums_total + "\t" + repeated_sums_total + "\t" + unique_sums_total);

        double ratio = (double)repeated_sums_total / (double)unique_sums_total;
        double distance_to_golden_ratio = Math.Abs(Numbers.PHI - ratio);

        str.AppendLine();
        str.AppendLine("Golden Ratio = " + Numbers.PHI + "...");
        str.AppendLine(repeated_sums_total + " / " + unique_sums_total + "  = " + ratio + "...");
        str.AppendLine("Difference   = " + distance_to_golden_ratio + "...");
        str.AppendLine("Difference % = " + distance_to_golden_ratio + " / " + Numbers.PHI + " = " +
            ((distance_to_golden_ratio / Numbers.PHI) * 100).ToString("0.0000") + "%");

        return str.ToString();
    }
    private static string CalculateBookStability(Client client, List<Chapter> chapters)
    {
        if (client == null)
            return null;
        if (chapters == null)
            return null;

        StringBuilder str = new StringBuilder();
        List<string> table1 = new List<string>();
        List<string> table2 = new List<string>();
        List<string> table3 = new List<string>();

        str.AppendLine("سورة #57 الحديد لا تتزحزح عن مكانها بغض النظر عن ترتيب الجداول تصاعدي أم تنازلي");
        str.AppendLine("Chapter #57 The Iron stays in place regardless of multiplication sorting order");
        str.AppendLine();

        table1.Add("#" + "\t" + "Chapter" + "\t" + "Number▲" + "\t" + "Verses" + "\t" + "Multiplication");
        long c_total = 0L;
        long v_total = 0L;
        long products_total = 0L;
        int count = 0;
        foreach (Chapter chapter in chapters)
        {
            count++;
            string name = chapter.Name;
            int c = chapter.SortedNumber;
            int v = chapter.Verses.Count;
            int product = c * v;
            c_total += c;
            v_total += v;
            products_total += product;
            table1.Add(count + "\t" + name + "\t" + c + "\t" + v + "\t" + product);
        }
        table1.Add("Sum" + "\t" + count + "\t" + c_total + "\t" + v_total + "\t" + products_total);


        table2.Add("#" + "\t" + "Chapter" + "\t" + "Number" + "\t" + "Verses" + "\t" + "Multiplication▲");
        c_total = 0L;
        v_total = 0L;
        products_total = 0L;
        count = 0;
        Chapter.CompareBy = ChapterCompareBy.CMultiplyV;
        Chapter.CompareOrder = ChapterCompareOrder.Ascending;
        chapters.Sort();
        foreach (Chapter chapter in chapters)
        {
            count++;
            string name = chapter.Name;
            int c = chapter.SortedNumber;
            int v = chapter.Verses.Count;
            int product = c * v;
            c_total += c;
            v_total += v;
            products_total += product;
            table2.Add(count + "\t" + name + "\t" + c + "\t" + v + "\t" + product);
        }
        table2.Add("Sum" + "\t" + count + "\t" + c_total + "\t" + v_total + "\t" + products_total);

        Chapter.CompareBy = ChapterCompareBy.CMultiplyV;
        Chapter.CompareOrder = ChapterCompareOrder.Descending;
        chapters.Sort();
        table3.Add("#" + "\t" + "Chapter" + "\t" + "Number" + "\t" + "Verses" + "\t" + "Multiplication▼");
        c_total = 0L;
        v_total = 0L;
        products_total = 0L;
        count = 0;
        foreach (Chapter chapter in chapters)
        {
            count++;
            string name = chapter.Name;
            int c = chapter.SortedNumber;
            int v = chapter.Verses.Count;
            int product = c * v;
            c_total += c;
            v_total += v;
            products_total += product;
            table3.Add(count + "\t" + name + "\t" + c + "\t" + v + "\t" + product);
        }
        table3.Add("Sum" + "\t" + count + "\t" + c_total + "\t" + v_total + "\t" + products_total);

        for (int i = 0; i < table1.Count; i++)
        {
            str.AppendLine(table1[i] + "\t\t" + table2[i] + "\t\t" + table3[i]);
        }
        return str.ToString();
    }

