    private static string DoVerseValuesByWordRootRepetitions(Client client, List<Verse> verses)
    {
        if (client == null)
            return null;
        if (verses == null)
            return null;

        StringBuilder str = new StringBuilder();
        if (verses.Count > 0)
        {
            str.Append
            (
                "#" + "\t" +
                "Id" + "\t" +
                "Chapter" + "\t" +
                "Verse" + "\t" +
                "Value" + "\t" +
                "WordRootRepetitions" + "\t" +
                "Text" + "\t"
            );
            str.AppendLine();

            int count = 0;
            foreach (Verse verse in verses)
            {
                StringBuilder word_value_frequencies = new StringBuilder();
                long value = 0L;
                foreach (Word word in verse.Words)
                {
                    int word_value_frequency = word.FrequencyByRoot;
                    word_value_frequencies.Append(word_value_frequency + " + ");
                    value += word_value_frequency;
                }
                if (word_value_frequencies.Length > 1)
                {
                    word_value_frequencies.Remove(word_value_frequencies.Length - 3, 3); // " + "
                }

                str.Append
                (
                    ++count + "\t" +
                    verse.Number + "\t" +
                    verse.Chapter.SortedNumber + "\t" +
                    verse.NumberInChapter + "\t" +
                    value + "\t" +
                    word_value_frequencies + "\t" +
                    verse.Text
                );
                str.AppendLine();
            }
        }
        return str.ToString();
    }
