    public static string PMultiply_EQ_PSum(Client client, string param, bool in_search_result)
    {
        StringBuilder str = new StringBuilder();
        StringBuilder sum_str = new StringBuilder();

        str.AppendLine("--------------------------------------------");
        str.AppendLine("P1" + "\t" + "P2" + "\t" + "P1×P2" + "\t" + "P1+...+P2");
        str.AppendLine("--------------------------------------------");

        long multiply = 0L;
        long sum = 0L;

        int count = Numbers.Primes.Count;
        for (int i = 0; i < count - 1; i++)
        {
            long p = Numbers.Primes[i];
            sum = p;
            sum_str.Length = 0;
            sum_str.Append(p + "+");

            for (int j = i + 1; j < count; j++)
            {
                long q = Numbers.Primes[j];
                sum += q;
                sum_str.Append(q + "+");

                multiply = p * q;
                if (multiply == sum)
                {
                    if (sum_str.Length > 0)
                        sum_str.Remove(sum_str.Length - 1, 1);

                    str.AppendLine(p + "\t" + q + "\t" + multiply + "\t" + sum_str);
                }
            }
        }
        return str.ToString();
    }
