        long sum = 0L;

        int count = Numbers.Composites.Count / 10;
        for (int i = 0; i < count - 1; i++)
        {
            long b = Numbers.Composites[i];
            sum = b;
            sum_str.Length = 0;
            sum_str.Append(b + "+");

            for (int j = i + 1; j < count; j++)
            {
                long d = Numbers.Composites[j];
                sum += d;
                sum_str.Append(d + "+");

                multiply = b * d;
                if (multiply == sum)
                {
                    if (sum_str.Length > 0)
                        sum_str.Remove(sum_str.Length - 1, 1);

                    str.AppendLine(b + "\t" + d + "\t" + multiply + "\t" + sum_str + "\r\n");
                }
            }
        }
        return str.ToString();
    }

