                int count = 0;
                foreach (Verse verse in verses)
                {
                    long value = 0L;
                    string text = "";
                    for (int i = 0; i < verse.Words.Count - 1; i++)
                    {
                        value = client.CalculateValue(verse.Words[i]);
                        text = verse.Words[i].Text + " ";

                        if (value > verse.Number)
                        {
                            continue;
                        }
                        else if (value == verse.Number)
                        {
                            str.AppendLine
                            (
                                ++count + "\t" +
                                verse.Chapter.Name + "\t" +
                                verse.NumberInChapter + "\t" +
                                verse.Number + "\t" +
                                text + "\t" +
                                value
                            );
                            continue;
                        }
                        else //if (value < verse.Number)
                        {
                            // allow multiple word-range matches within the same verse
                            for (int j = i + 1; j < verse.Words.Count; j++)
                            {
                                value += client.CalculateValue(verse.Words[j]);
                                if (value > verse.Number) break;

                                text += verse.Words[j].Text;
                                if (value == verse.Number)
                                {
                                    str.AppendLine
                                    (
                                        ++count + "\t" +
                                        verse.Chapter.Name + "\t" +
                                        verse.NumberInChapter + "\t" +
                                        verse.Number + "\t" +
                                        text + "\t" +
                                        value
                                    );
                                    break;
                                }

                                text += " ";
                            }
                        }
                    }
                }
            }
        }

        return str.ToString();
    }
    public static string VersesWords_EQ_VerseNumber(Client client, string param, bool in_search_result)
    {
        if (client == null)
            return null;
        if (client.NumericalSystem == null)
            return null;

        StringBuilder str = new StringBuilder();

        List<Verse> verses = GetSourceVerses(client, in_search_result);
        if (verses != null)
        {
            if (verses.Count > 0)
            {
                str.AppendLine("#" + "\t" + "Chapter" + "\t" + "Verse" + "\t" + "Number" + "\t" + "Words" + "\t" + "Value");

                List<Word> words = new List<Word>();
                foreach (Verse verse in verses)
                {
                    words.AddRange(verse.Words);
                }

                int count = 0;
                for (int i = 0; i < words.Count - 1; i++)
                {
                    long value = client.CalculateValue(words[i]);
                    string text = words[i].Text + " ";
                    if (value == words[i].Verse.Number)
                    {
                        str.AppendLine
                        (
                            ++count + "\t" +
                            words[i].Verse.Chapter.Name + "\t" +
                            words[i].Verse.NumberInChapter + "\t" +
                            words[i].Verse.Number + "\t" +
                            text + "\t" +
                            value
                        );
                    }

                    for (int j = i + 1; j < words.Count; j++)
                    {
                        value += client.CalculateValue(words[j]);
                        if (value > words[i].Verse.Number) break;

                        text += words[j].Text;
                        if (value == words[i].Verse.Number)
                        {
                            if (words[i].Verse.Chapter != words[j].Verse.Chapter)
                            {
                                str.AppendLine
                                (
                                    ++count + "\t" +
                                    words[j].Verse.Chapter.Name + "-" + words[i].Verse.Chapter.Name + "\t" +
                                    words[i].Verse.NumberInChapter + "-" + words[j].Verse.NumberInChapter + "\t" +
                                    words[i].Verse.Number + "-" + words[j].Verse.Number + "\t" +
                                    text + "\t" +
                                    value
                                );
                            }
                            else if (words[i].Verse != words[j].Verse)
                            {
                                str.AppendLine
                                (
                                    ++count + "\t" +
                                    words[i].Verse.Chapter.Name + "\t" +
                                    words[i].Verse.NumberInChapter + "-" + words[j].Verse.NumberInChapter + "\t" +
                                    words[i].Verse.Number + "-" + words[j].Verse.Number + "\t" +
                                    text + "\t" +
                                    value
                                );
                            }
                            else
                            {
                                str.AppendLine
                                (
                                    ++count + "\t" +
                                    words[i].Verse.Chapter.Name + "\t" +
                                    words[i].Verse.NumberInChapter + "\t" +
                                    words[i].Verse.Number + "\t" +
                                    text + "\t" +
                                    value
                                );
                            }

                            break;
                        }
                        text += " ";
                    }
                }
            }
        }

        return str.ToString();
    }

