    public static string VerseValueByWordFrequency(Client client, string param, bool in_search_result)
    {
        if (client == null)
            return null;

        StringBuilder str = new StringBuilder();

        List<Verse> verses = GetSourceVerses(client, in_search_result);
        if (verses != null)
        {
            if (verses.Count > 0)
            {
                str.AppendLine("#" + "\t" + "Chapter" + "\t" + "Verse" + "\t" + "Words" + "\t" + "Value" + "\t" + "Sum of Word Frequencies");

                int count = 0;
                foreach (Verse verse in verses)
                {
                    long verse_value = 0L;
                    string verse_value_str = "";
                    foreach (Word word in verse.Words)
                    {
                        verse_value += word.Frequency;
                        verse_value_str += word.Frequency + " + ";
                    }
                    verse_value_str = verse_value_str.Remove(verse_value_str.Length - 3);

                    str.AppendLine
                    (
                        ++count + "\t" +
                        verse.Chapter.SortedNumber + "\t" +
                        verse.NumberInChapter + "\t" +
                        verse.Words.Count + "\t" +
                        verse_value + "\t" +
                        verse_value_str
                    );
                }
            }
        }

        return str.ToString();
    }
