    private static string SymmetricalPCChapters(Client client, string param, bool in_search_result)
    {
        if (client == null)
            return null;
        if (client.Book == null)
            return null;
        List<Verse> verses = GetSourceVerses(client, in_search_result);
        if (verses != null)
        {
            List<Chapter> chapters = client.Book.GetChapters(verses);
            if (chapters != null)
            {
                StringBuilder str = new StringBuilder();
                str.AppendLine("#" + "\t" + "C1" + "\t" + "V1" + "\t" + "C2" + "\t" + "V2");
                int count = 0;
                for (int i = 0; i < chapters.Count; i++)
                {
                    str.AppendLine();

                    int c1 = chapters[i].SortedNumber;
                    int value1 = chapters[i].Verses.Count;
                    int c1i = Numbers.PrimeIndexOf(c1);
                    if (c1i == -1)
                        continue;

                    for (int j = 0; j < chapters.Count; j++)
                    {
                        int c2 = chapters[j].SortedNumber;
                        int value2 = chapters[j].Verses.Count;
                        int c2i = Numbers.CompositeIndexOf(c2);
                        if (c2i == -1)
                            continue;

                        if (c1i == c2i)
                        {
                            count++;
                            str.AppendLine(count + "\t" + c1 + "\t" + value1 + "\t" + c2 + "\t" + value2);
                        }
                    }
                }
                return str.ToString();
            }
        }
        return null;
    }
