        List<Verse> verses = GetSourceVerses(client, in_search_result);
        if (verses != null)
        {
            if (verses.Count > 0)
            {
                str.AppendLine
                (
                    "#" + "\t" +
                    "Word1" + "\t" +
                    "Word2" + "\t" +
                    "Text1" + "\t" +
                    "Text2" + "\t" +
                    "Value1" + "\t" +
                    "Value2" + "\t" +
                    "Verse1" + "\t" +
                    "Verse2"
                );

                List<Word> words = new List<Word>();
                foreach (Verse verse in verses)
                {
                    words.AddRange(verse.Words);
                }

                int count = 0;
                for (int i = 0; i < words.Count - 1; i++)
                {
                    int j = i + 1;

                    long target1 = client.CalculateValue(words[i]);
                    long target2 = client.CalculateValue(words[j]);
                    long T = target1 * (target1 + 1) / 2;
                    if (target2 == T)
                    {
                        str.AppendLine
                        (
                            ++count + "\t" +
