    private static string DoBookFirstHalfEvenVerses(Client client, List<Verse> verses)
    {
        if (client == null)
            return null;
        if (client.Book == null)
            return null;
        if (verses == null)
            return null;
        List<Chapter> chapters = client.Book.GetChapters(verses);

        int chapter_count = 0;
        long verse_count = 0;
        long verse_sequence_sum = 0;
        foreach (Chapter chapter in chapters)
        {
            if (chapter.SortedNumber <= (chapters.Count / 2))
            {
                if (Numbers.IsEven(chapter.Verses.Count))
                {
                    chapter_count++;
                    foreach (Verse verse in chapter.Verses)
                    {
                        verse_count++;
                        verse_sequence_sum += verse.Number;
                    }
                }
            }
        }

        return (chapter_count + " chapters in first half of the Quran with even verses.\r\n" + verse_count + " verses with sum of Book-level verses numbers = " + verse_sequence_sum);
    }
