    private static string DoDoubleWords(Client client, List<Verse> verses)
    {
        if (client == null)
            return null;
        if (client.NumericalSystem == null)
            return null;

        StringBuilder str = new StringBuilder();
        if (verses != null)
        {
            if (verses.Count > 0)
            {
                str.AppendLine
                (
                    "#" + "\t" +
                    "inQuran" + "\t" +
                    "inChap" + "\t" +
                    "Chapter" + "\t" +
                    "Verse" + "\t" +
                    "Word" + "\t" +
                    "Text" + "\t" +
                    "Order" + "\t" +
                    "Total" + "\t" +
                    "Value" + "\t" +
                    "Verse"
                );

                List<Word> words = new List<Word>();
                foreach (Verse verse in verses)
                {
                    words.AddRange(verse.Words);
                }

                int count = 0;
                for (int i = 0; i < words.Count - 1; i++)
                {
                    int j = i + 1;
                    if (words[i].Text.Simplify(client.NumericalSystem.TextMode) ==
                        words[j].Text.Simplify(client.NumericalSystem.TextMode)
                       )
                    {
                        str.AppendLine
                        (
                            ++count + "\t" +
                            words[i].Number + "\t" +
                            words[i].NumberInChapter + "\t" +
                            words[i].Verse.Chapter.SortedNumber + "\t" +
                            words[i].Verse.NumberInChapter + "\t" +
                            words[i].NumberInVerse + "\t" +
                            words[i].Text + "\t" +
                            words[i].Occurrence + "\t" +
                            words[i].Frequency + "\t" +
                            words[i].Value + "\t" +
                            words[i].Verse.Text
                        );
                        str.AppendLine
                        (
                            count + "\t" +
                            words[j].Number + "\t" +
                            words[j].NumberInChapter + "\t" +
                            words[j].Verse.Chapter.SortedNumber + "\t" +
                            words[j].Verse.NumberInChapter + "\t" +
                            words[j].NumberInVerse + "\t" +
                            words[j].Text + "\t" +
                            words[j].Occurrence + "\t" +
                            words[j].Frequency + "\t" +
                            words[j].Value + "\t" +
                            words[j].Verse.Text
                        );
                    }
                }
            }
        }
        return str.ToString();
    }
    private static string DoConsecutiveWordValues(Client client, List<Verse> verses)
    {
        if (client == null)
            return null;
        if (client.NumericalSystem == null)
            return null;

        StringBuilder str = new StringBuilder();
        if (verses != null)
        {
            if (verses.Count > 0)
            {
                str.AppendLine
                (
                    "#" + "\t" +
                    "Chapter" + "\t" +
                    "Verse" + "\t" +
                    "Word" + "\t" +
                    "Text" + "\t" +
                    "Value" + "\t" +
                    "Verse"
                );

                List<Word> words = new List<Word>();
                foreach (Verse verse in verses)
                {
                    words.AddRange(verse.Words);
                }

                int count = 0;
                for (int i = 0; i < words.Count - 1; i++)
                {
                    long target1 = client.CalculateValue(words[i]);
                    long target2 = client.CalculateValue(words[i + 1]);
                    if (target2 == (target1 + 1L))
                    {
                        str.AppendLine
                        (
                            ++count + "\t" +
                            words[i].Verse.Chapter.SortedNumber + "\t" +
                            words[i].Verse.NumberInChapter + "\t" +
                            words[i].NumberInVerse + "\t" +
                            words[i].Text + "\t" +
                            words[i].Value + "\t" +
                            words[i].Verse.Text
                        );
                        str.AppendLine
                        (
                            count + "\t" +
                            words[i + 1].Verse.Chapter.SortedNumber + "\t" +
                            words[i + 1].Verse.NumberInChapter + "\t" +
                            words[i + 1].NumberInVerse + "\t" +
                            words[i + 1].Text + "\t" +
                            words[i + 1].Value + "\t" +
                            words[i + 1].Verse.Text
                        );
                    }
                }
            }
        }
        return str.ToString();
    }
