    private static string DoChapterInformation(Client client, List<Chapter> chapters)
    {
        if (client == null)
            return null;
        if (chapters == null)
            return null;

        StringBuilder str = new StringBuilder();

        str.Append("#" + "\t" + "Name" + "\t" + "Transliteration" + "\t" + "English" + "\t" + "Place" + "\t" + "Order" + "\t" + "Page" + "\t" + "Chapter" + "\t" + "Verses" + "\t" + "Words" + "\t" + "Letters" + "\t" + "Unique" + "\t" + "Value" + "\t" + "Factors" + "\t" + "P" + "\t" + "AP" + "\t" + "XP" + "\t" + "C" + "\t" + "AC" + "\t" + "XC" + "\t");

        NumericalSystem numerical_system = client.NumericalSystem;
        if (numerical_system != null)
        {
            if (numerical_system.LetterValues.Keys.Count > 0)
            {
                foreach (char key in numerical_system.LetterValues.Keys)
                {
                    str.Append(key.ToString() + "\t");
                }
                if (str.Length > 1)
                {
                    str.Remove(str.Length - 1, 1); // \t
                }
                str.AppendLine();
            }

            int count = 0;
            foreach (Chapter chapter in chapters)
            {
                str.Append((++count).ToString() + "\t");
                str.Append(chapter.Name + "\t");
                str.Append(chapter.TransliteratedName + "\t");
                str.Append(chapter.EnglishName + "\t");
                str.Append(chapter.RevelationPlace.ToString() + "\t");
                str.Append(chapter.RevelationOrder.ToString() + "\t");
                str.Append(chapter.Verses[0].Page.Number.ToString() + "\t");
                str.Append(chapter.SortedNumber.ToString() + "\t");
                str.Append(chapter.Verses.Count.ToString() + "\t");
                str.Append(chapter.Words.Count.ToString() + "\t");
                str.Append(chapter.Letters.Count.ToString() + "\t");
                str.Append(chapter.UniqueLetters.Count.ToString() + "\t");

                long value = client.CalculateValue(chapter);
                str.Append(value.ToString() + "\t");
                str.Append(Numbers.FactorizeToString(value) + "\t");

                int p = Numbers.PrimeIndexOf(value) + 1;
                int ap = Numbers.AdditivePrimeIndexOf(value) + 1;
                int xp = Numbers.NonAdditivePrimeIndexOf(value) + 1;
                int c = Numbers.CompositeIndexOf(value) + 1;
                int ac = Numbers.AdditiveCompositeIndexOf(value) + 1;
                int xc = Numbers.NonAdditiveCompositeIndexOf(value) + 1;
                str.Append((p == 0 ? "-" : p.ToString()) + "\t"
                        + (ap == 0 ? "-" : ap.ToString()) + "\t"
                        + (xp == 0 ? "-" : xp.ToString()) + "\t"
                        + (c == 0 ? "-" : c.ToString()) + "\t"
                        + (ac == 0 ? "-" : ac.ToString()) + "\t"
                        + (xc == 0 ? "-" : xc.ToString())
                        );
                str.Append("\t");

                if (numerical_system.LetterValues.Keys.Count > 0)
                {
                    foreach (char key in numerical_system.LetterValues.Keys)
                    {
                        str.Append(chapter.GetLetterFrequency(key) + "\t");
                    }
                    if (str.Length > 1)
                    {
                        str.Remove(str.Length - 1, 1); // \t
                    }
                    str.AppendLine();
                }
            }
            if (str.Length > 2)
            {
                str.Remove(str.Length - 2, 2);
            }
        }
        return str.ToString();
    }
    private static string DoChapterLetterRatios(Client client, List<Chapter> chapters)
    {
        if (client == null)
            return null;
        if (chapters == null)
            return null;

        StringBuilder str = new StringBuilder();

        str.Append("#" + "\t" + "Name" + "\t" + "Chapter" + "\t" + "Verses" + "\t" + "Words" + "\t" + "Letters" + "\t");

        NumericalSystem numerical_system = client.NumericalSystem;
        if (numerical_system != null)
        {
            if (numerical_system.LetterValues.Keys.Count > 0)
            {
                foreach (char key in numerical_system.LetterValues.Keys)
                {
                    str.Append(key.ToString() + "\t");
                }
                if (str.Length > 1)
                {
                    str.Remove(str.Length - 1, 1); // \t
                }
                str.AppendLine();
            }

            int count = 0;
            long sum = 0;
            long chapter_sum = 0;
            long verse_sum = 0;
            long word_sum = 0;
            long letter_sum = 0;

            foreach (Chapter chapter in chapters)
            {
                sum += ++count;
                chapter_sum += chapter.SortedNumber;
                verse_sum += chapter.Verses.Count;
                word_sum += chapter.Words.Count;
                letter_sum += chapter.Letters.Count;

                str.Append(count + "\t");
                str.Append(chapter.Name + "\t");
                str.Append(chapter.SortedNumber.ToString() + "\t");
                str.Append(chapter.Verses.Count.ToString() + "\t");
                str.Append(chapter.Words.Count.ToString() + "\t");
                str.Append(chapter.Letters.Count.ToString() + "\t");

                if (numerical_system.LetterValues.Keys.Count > 0)
                {
                    foreach (char key in numerical_system.LetterValues.Keys)
                    {
                        str.Append((((double)chapter.GetLetterFrequency(key) * 100.0D) / chapter.Letters.Count) + "%" + "\t");
                    }
                    if (str.Length > 1)
                    {
                        str.Remove(str.Length - 1, 1); // \t
                    }
                    str.AppendLine();
                }
            }
            if (str.Length > 2)
            {
                str.Remove(str.Length - 2, 2);
            }

            str.AppendLine();
            str.AppendLine(sum + "\t" + "Sum" + "\t" + chapter_sum + "\t" + verse_sum + "\t" + word_sum + "\t" + letter_sum);
        }

        return str.ToString();
    }
    private static string DoVerseInformation(Client client, List<Verse> verses)
    {
        if (client == null)
            return null;
        if (verses == null)
            return null;

        StringBuilder str = new StringBuilder();

        str.Append("#" + "\t" + "Number" + "\t" + "Page" + "\t" + "Chapter" + "\t" + "Verse" + "\t" + "Words" + "\t" + "Letters" + "\t" + "Unique" + "\t" + "Value" + "\t" + "Factors" + "\t" + "P" + "\t" + "AP" + "\t" + "XP" + "\t" + "C" + "\t" + "AC" + "\t" + "XC" + "\t");

        NumericalSystem numerical_system = client.NumericalSystem;
        if (numerical_system != null)
        {
            foreach (char key in numerical_system.LetterValues.Keys)
            {
                str.Append(key.ToString() + "\t");
            }
            str.Append("Text");
            str.AppendLine();

            int count = 0;
            foreach (Verse verse in verses)
            {
                str.Append((++count).ToString() + "\t");
                str.Append(verse.Number.ToString() + "\t");
                str.Append(verse.Page.Number.ToString() + "\t");
                str.Append(verse.Chapter.SortedNumber.ToString() + "\t");
                str.Append(verse.NumberInChapter.ToString() + "\t");
                str.Append(verse.Words.Count.ToString() + "\t");
                str.Append(verse.Letters.Count.ToString() + "\t");
                str.Append(verse.UniqueLetters.Count.ToString() + "\t");

                long value = client.CalculateValue(verse);
                str.Append(value.ToString() + "\t");
                str.Append(Numbers.FactorizeToString(value) + "\t");

                int p = Numbers.PrimeIndexOf(value) + 1;
                int ap = Numbers.AdditivePrimeIndexOf(value) + 1;
                int xp = Numbers.NonAdditivePrimeIndexOf(value) + 1;
                int c = Numbers.CompositeIndexOf(value) + 1;
                int ac = Numbers.AdditiveCompositeIndexOf(value) + 1;
                int xc = Numbers.NonAdditiveCompositeIndexOf(value) + 1;
                str.Append((p == 0 ? "-" : p.ToString()) + "\t"
                        + (ap == 0 ? "-" : ap.ToString()) + "\t"
                        + (xp == 0 ? "-" : xp.ToString()) + "\t"
                        + (c == 0 ? "-" : c.ToString()) + "\t"
                        + (ac == 0 ? "-" : ac.ToString()) + "\t"
                        + (xc == 0 ? "-" : xc.ToString())
                             );
                str.Append("\t");

                foreach (char letter in numerical_system.LetterValues.Keys)
                {
                    str.Append(verse.GetLetterFrequency(letter).ToString() + "\t");
                }

                str.Append(verse.Text);

                str.AppendLine();
            }
            if (str.Length > 2)
            {
                str.Remove(str.Length - 2, 2);
            }
        }
        return str.ToString();
    }
    private static string DoVerseStartLetters(Client client, List<Verse> verses)
    {
        if (client == null)
            return null;
        if (verses == null)
            return null;

        StringBuilder str = new StringBuilder();
        str.AppendLine("Letter" + "\t" + "Frequency");

        foreach (char c in Constants.ARABIC_LETTERS)
        {
            int count = 0;
            foreach (Verse verse in verses)
            {
                char first = '\0';
                for (int i = 0; i < verse.Text.Length; i++)
                {
                    if (Constants.ARABIC_LETTERS.Contains(verse.Text[i]))
                    {
                        first = verse.Text[i];
                        break;
                    }
                }

                if (c == first)
                {
                    count++;
                }
            }
            str.AppendLine(c.ToString() + "\t" + count.ToString());
        }
        if (str.Length > 2)
        {
            str.Remove(str.Length - 2, 2); // \r\n
        }

        return str.ToString();
    }
    private static string DoVerseEndLetters(Client client, List<Verse> verses)
    {
        if (client == null)
            return null;
        if (verses == null)
            return null;

        StringBuilder str = new StringBuilder();
        str.AppendLine("Letter" + "\t" + "Frequency");

        foreach (char c in Constants.ARABIC_LETTERS)
        {
            int count = 0;
            foreach (Verse verse in verses)
            {
                char last = '\0';
                for (int i = verse.Text.Length - 1; i >= 0; i--)
                {
                    if (Constants.ARABIC_LETTERS.Contains(verse.Text[i]))
                    {
                        last = verse.Text[i];
                        break;
                    }
                }

                if (c == last)
                {
                    count++;
                }
            }
            str.AppendLine(c.ToString() + "\t" + count.ToString());
        }
        if (str.Length > 2)
        {
            str.Remove(str.Length - 2, 2); // \r\n
        }

        return str.ToString();
    }
    private static string DoWordInformation(Client client, List<Word> words)
    {
        if (client == null)
            return null;
        if (words == null)
            return null;
        if (WordPartGrammar.Language == null)
            return null;

        StringBuilder str = new StringBuilder();
        if (words.Count > 0)
        {
            str.AppendLine
            (
                "#" + "\t" +
                "Number" + "\t" +
                "InChap" + "\t" +
                "Chapter" + "\t" +
                "Verse" + "\t" +
                "Word" + "\t" +
                "Occurrence" + "\t" +
                "Frequency" + "\t" +
                "Text" + "\t" +
                "Transliteration" + "\t" +
                "Grammar" + "\t" +
                "Roots" + "\t" +
                "Meaning" + "\t" +
                "Letters" + "\t" +
                "Value" + "\t" + "Factors" + "\t" + "P" + "\t" + "AP" + "\t" + "XP" + "\t" + "C" + "\t" + "AC" + "\t" + "XC"
            );

            int count = 0;
            foreach (Word word in words)
            {
                StringBuilder roots_str = new StringBuilder();
                List<string> roots = word.Roots;
                if (roots != null)
                {
                    if (roots.Count > 0)
                    {
                        foreach (string root in roots)
                        {
                            roots_str.Append(root + "|");
                        }
                        roots_str.Remove(roots_str.Length - 1, 1);
                    }
                }

                StringBuilder parts_grammar_str = new StringBuilder();
                if (word.Parts.Count > 0)
                {
                    foreach (WordPart word_part in word.Parts)
                    {
                        parts_grammar_str.Append(
                            ((word_part.Grammar.Position != null) ? (WordPartGrammar.Language["Grammar_" + word_part.Grammar.Position]) : "") +
                            //"," +
                            //((word_part.Grammar.Attribute != null) ? (WordPartGrammar.Language["Grammar_" + word_part.Grammar.Attribute]) : "") + "," +
                            //((word_part.Grammar.Position == "V") ? ((word_part.Grammar.Qualifier != null) ? (WordPartGrammar.Language["Grammar_" + word_part.Grammar.Qualifier]) : "") : "") + "," +
                            //((word_part.Grammar.PersonDegree != null) ? (WordPartGrammar.Language["Grammar_" + word_part.Grammar.PersonDegree]) : "") + "," +
                            //((word_part.Grammar.PersonGender != null) ? (WordPartGrammar.Language["Grammar_" + word_part.Grammar.PersonGender]) : "") + "," +
                            //((word_part.Grammar.PersonNumber != null) ? (WordPartGrammar.Language["Grammar_" + word_part.Grammar.PersonNumber]) : "") + "," +
                            //((word_part.Grammar.Mood != null) ? (WordPartGrammar.Language["Grammar_" + word_part.Grammar.Mood]) : "") + "," +
                            //word_part.Grammar.Lemma.ToArabic() + "," +
                            //word_part.Grammar.Root.ToArabic() + "," +
                            //word_part.Grammar._SpecialGroup.ToArabic() +
                            "|"
                            );
                    }
                    parts_grammar_str.Replace("  ", " ");
                    parts_grammar_str.Replace(" |", "|");
                    parts_grammar_str.Replace("| ", "|");
                    parts_grammar_str.Remove(parts_grammar_str.Length - 1, 1); // remove last "|"
                }

                str.Append
                (
                    ++count + "\t" +
                    word.Number + "\t" +
                    word.NumberInChapter + "\t" +
                    word.Verse.Chapter.SortedNumber + "\t" +
                    word.Verse.NumberInChapter + "\t" +
                    word.NumberInVerse + "\t" +
                    word.Occurrence + "\t" +
                    word.Frequency + "\t" +
                    word.Text + "\t" +
                    word.Transliteration + "\t" +
                    parts_grammar_str + "\t" +
                    roots_str + "\t" +
                    word.Meaning + "\t" +
                    word.Letters.Count + "\t"
                );

                long value = client.CalculateValue(word);
                str.Append(value.ToString() + "\t");
                str.Append(Numbers.FactorizeToString(value) + "\t");

                int p = Numbers.PrimeIndexOf(value) + 1;
                int ap = Numbers.AdditivePrimeIndexOf(value) + 1;
                int xp = Numbers.NonAdditivePrimeIndexOf(value) + 1;
                int c = Numbers.CompositeIndexOf(value) + 1;
                int ac = Numbers.AdditiveCompositeIndexOf(value) + 1;
                int xc = Numbers.NonAdditiveCompositeIndexOf(value) + 1;
                str.Append((p == 0 ? "-" : p.ToString()) + "\t"
                        + (ap == 0 ? "-" : ap.ToString()) + "\t"
                        + (xp == 0 ? "-" : xp.ToString()) + "\t"
                        + (c == 0 ? "-" : c.ToString()) + "\t"
                        + (ac == 0 ? "-" : ac.ToString()) + "\t"
                        + (xc == 0 ? "-" : xc.ToString())
                             );
                str.AppendLine();
            }
        }
        return str.ToString();
    }
