                            ((word_part.Grammar.Position != null) ? (WordPartGrammar.Language["Grammar_" + word_part.Grammar.Position]) : "") + "\t" +
                            ((word_part.Grammar.Attribute != null) ? (WordPartGrammar.Language["Grammar_" + word_part.Grammar.Attribute]) : "") + "\t" +
                            ((word_part.Grammar.Position == "V") ? ((word_part.Grammar.Qualifier != null) ? (WordPartGrammar.Language["Grammar_" + word_part.Grammar.Qualifier]) : "") : "") + "\t" +
                            ((word_part.Grammar.PersonDegree != null) ? (WordPartGrammar.Language["Grammar_" + word_part.Grammar.PersonDegree]) : "") + "\t" +
                            ((word_part.Grammar.PersonGender != null) ? (WordPartGrammar.Language["Grammar_" + word_part.Grammar.PersonGender]) : "") + "\t" +
                            ((word_part.Grammar.PersonNumber != null) ? (WordPartGrammar.Language["Grammar_" + word_part.Grammar.PersonNumber]) : "") + "\t" +
                            ((word_part.Grammar.Mood != null) ? (WordPartGrammar.Language["Grammar_" + word_part.Grammar.Mood]) : "") + "\t" +
                            word_part.Grammar.Lemma.ToArabic() + "\t" +
                            word_part.Grammar.Root.ToArabic() + "\t" +
                            word_part.Grammar.SpecialGroup.ToArabic()
                        );
                    }
                }
            }
        }
        return str.ToString();
    }
    private static string DoLetterInformation(Client client, List<Letter> letters)
    {
        if (client == null)
            return null;
        if (letters == null)
            return null;

        StringBuilder str = new StringBuilder();
        if (letters.Count > 0)
        {
            str.Append
            (
                "#" + "\t" +
                "Chapter" + "\t" +
                "Verse" + "\t" +
                "Word" + "\t" +
                "Letter" + "\t" +
                "InChap" + "\t" +
                "InVerse" + "\t" +
                "InWord" + "\t" +
                "Value" + "\t" +
                "Text" + "\t" +
                "Word" + "\r\n"
            );

            long count_sum = 0;
            long chapter_number_sum = 0;
            long verse_number_in_chapter_sum = 0;
            long word_number_in_verse_sum = 0;
            long letter_number_sum = 0;
            long letter_number_in_chapter_sum = 0;
            long letter_number_in_verse_sum = 0;
            long letter_number_in_word_sum = 0;
            long letter_value_sum = 0L;

            int count = 0;
            foreach (Letter letter in letters)
            {
                int chapter_number = letter.Word.Verse.Chapter.SortedNumber;
                int verse_number_in_chapter = letter.Word.Verse.NumberInChapter;
                int word_number_in_verse = letter.Word.NumberInVerse;
                int letter_number = letter.Number;
                int letter_number_in_chapter = letter.NumberInChapter;
                int letter_number_in_verse = letter.NumberInVerse;
                int letter_number_in_word = letter.NumberInWord;
                long letter_value = client.CalculateValue(letter);
                str.Append
                (
                    (++count).ToString() + "\t" +
                    chapter_number.ToString() + "\t" +
                    verse_number_in_chapter.ToString() + "\t" +
                    word_number_in_verse.ToString() + "\t" +
                    letter_number.ToString() + "\t" +
                    letter_number_in_chapter.ToString() + "\t" +
                    letter_number_in_verse.ToString() + "\t" +
                    letter_number_in_word.ToString() + "\t" +
                    letter_value.ToString() + "\t" +
                    letter.Text + "\t" +
                    letter.Word.ToString() + "\r\n"
                );
                count_sum += count;
                chapter_number_sum += chapter_number;
                verse_number_in_chapter_sum += verse_number_in_chapter;
                word_number_in_verse_sum += word_number_in_verse;
                letter_number_sum += letter_number;
                letter_number_in_chapter_sum += letter_number_in_chapter;
                letter_number_in_verse_sum += letter_number_in_verse;
                letter_number_in_word_sum += letter_number_in_word;
                letter_value_sum += letter_value;
            }

            str.Append
            (
                count_sum.ToString() + "\t" +
                chapter_number_sum.ToString() + "\t" +
                verse_number_in_chapter_sum.ToString() + "\t" +
                word_number_in_verse_sum.ToString() + "\t" +
                letter_number_sum.ToString() + "\t" +
                letter_number_in_chapter_sum.ToString() + "\t" +
                letter_number_in_verse_sum.ToString() + "\t" +
                letter_number_in_word_sum.ToString() + "\t" +
                letter_value_sum.ToString() + "\t" +
                "" + "\t" +
                "" + "\r\n"
            );
        }
        return str.ToString();
    }
    private static string DoLetterFrequencySums(Client client, List<Verse> verses, string phrase)
    {
        if (client == null)
            return null;
        if (verses == null)
            return null;

        StringBuilder str = new StringBuilder();
        if (verses.Count > 0)
        {
            str.AppendLine("Phrase" + "\t" + phrase);
            str.AppendLine("Verse" + "\t" + "LFSum" + "\t" + "Address" + "\t" + "Text");

            Dictionary<Verse, int> letter_frequency_sums = new Dictionary<Verse, int>();
            if (letter_frequency_sums != null)
            {
                CalculateLetterFrequencySums(client, verses, ref letter_frequency_sums, phrase);
                if (letter_frequency_sums != null)
                {
                    foreach (Verse verse in letter_frequency_sums.Keys)
                    {
                        str.AppendLine
                        (
                            verse.Number + "\t" + letter_frequency_sums[verse] + "\t" + verse.Address + "\t" + verse.Text
                        );
                    }
                }
            }
        }
        return str.ToString();
    }
    private static void CalculateLetterFrequencySums(Client client, List<Verse> verses, ref Dictionary<Verse, int> letter_frequency_sums, string phrase)
    {
        if (client == null)
            return;
        if (client.NumericalSystem == null)
            return;
        if (verses == null)
            return;

        if (verses.Count > 0)
        {
            foreach (Verse verse in verses)
            {
                int lfsum = client.CalculateLetterFrequencySum(verse.Text, phrase, FrequencySearchType.DuplicateLetters, false);
                letter_frequency_sums.Add(verse, lfsum);
            }
        }
    }
    private static string GetDuplicateChapterValues(Client client, List<Chapter> chapters)
    {
        if (client == null)
            return null;
        if (chapters == null)
            return null;

        StringBuilder str = new StringBuilder();
        Dictionary<long, int> value_frequencies = new Dictionary<long, int>();
        Dictionary<long, string> duplicate_values = new Dictionary<long, string>();
        foreach (NumericalSystem ns in client.LoadedNumericalSystems.Values)
        {
            if (ns != null)
            {
                if (ns.TextMode == client.NumericalSystem.TextMode)
                {
                    value_frequencies.Clear();
                    duplicate_values.Clear();
                    int duplicates = 0;
                    foreach (Chapter chapter in chapters)
                    {
                        long value = ns.CalculateValue(chapter.Text);
                        if (value > 0)
                        {
                            if (!value_frequencies.ContainsKey(value))
                            {
                                value_frequencies.Add(value, 1);
                            }
                            else
                            {
                                value_frequencies[value]++;
                                duplicates++;
                            }

                            if (!duplicate_values.ContainsKey(value))
                            {
                                duplicate_values.Add(value, chapter.Name);
                            }
                            else
                            {
                                duplicate_values[value] += "\t" + chapter.Name;
                            }
                        }
                    }

                    if (duplicates > 0)
                    {
                        str.AppendLine("--------------------------------------------------------------------------");
                        str.AppendLine(duplicates + " chapter group" + ((duplicates > 1) ? "s" : "") + " with the same value in " + ns.Name.Substring(ns.TextMode.Length + 1));
                        str.AppendLine("--------------------------------------------------------------------------");
                        str.AppendLine("Value" + "\t" + "Chapters");
                        str.AppendLine("--------------------------------------------------------------------------");
                        foreach (long value in duplicate_values.Keys)
                        {
                            if (duplicate_values[value].Contains("\t"))
                            {
                                str.AppendLine(value.ToString() + "\t" + duplicate_values[value]);
                            }
                        }
                        str.AppendLine("--------------------------------------------------------------------------");
                        str.AppendLine();
                    }
                }
            }
        }

        return str.ToString();
    }
