    private static List<string> DoPrimeWords(Client client, List<Verse> verses)
    {
        if (client == null)
            return null;
        if (verses == null)
            return null;

        List<string> result = new List<string>();

        List<Word> words = new List<Word>();
        foreach (Verse verse in verses)
        {
            words.AddRange(verse.Words);
        }

        int count = 0;
        for (int i = 0; i < words.Count; i++)
        {
            if (Numbers.IsPrime(i + 1))
            {
                result.Add(++count + "\t" + words[i].Number + "\t" + words[i].Text);
            }
        }

        return result;
    }
