    private static string DoRepeatedLetters(Client client, List<Verse> verses, string param)
    {
        if (client == null)
            return null;
        if (verses == null)
            return null;
        if (param == null)
            return null;

        int gap = 0;
        if (int.TryParse(param, out gap))
        { }
        StringBuilder str = new StringBuilder();
        if (verses.Count > 0)
        {
            str.AppendLine("LL" + "\t" + "Count");

            SortedDictionary<char, int> result = new SortedDictionary<char, int>();
            foreach (Verse verse in verses)
            {
                foreach (Word word in verse.Words)
                {
                    for (int i = 0; i < word.Letters.Count - (gap + 1); i++)
                    {
                        if (word.Letters.Count > i + (gap + 1))
                        {
                            if (word.Letters[i].Character == word.Letters[i + (gap + 1)].Character)
                            {
                                if (result.ContainsKey(word.Letters[i].Character))
                                {
                                    result[word.Letters[i].Character]++;
                                }
                                else
                                {
                                    result.Add(word.Letters[i].Character, 1);
                                }
                            }
                        }
                    }
                }
            }
            foreach (char key in result.Keys)
            {
                str.AppendLine(key.ToString() + key.ToString() + "\t" + result[key].ToString());
            }
        }
        return str.ToString();
    }
    private static string DoRepeatedWords(Client client, List<Verse> verses, string param)
    {
        if (client == null)
            return null;
        if (client.NumericalSystem == null)
            return null;
        if (verses == null)
            return null;
        if (param == null)
            return null;

        int gap = 0;
        if (int.TryParse(param, out gap))
        { }
        StringBuilder str = new StringBuilder();
        if (verses.Count > 0)
        {
            str.AppendLine
            (
                "#" + "\t" +
                "Word1" + "\t" +
                "Word2" + "\t" +
                "V#" + "\t" +
                "C" + "\t" +
                "V" + "\t" +
                "W1" + "\t" +
                "W2" + "\t" +
                "Verse"
            );

            int count = 0;
            foreach (Verse verse in verses)
            {
                List<Word> words = verse.Words;
                for (int i = 0; i < words.Count - (gap + 1); i++)
                {
                    int j = i + (gap + 1);
                    if (words[i].Text.Simplify(client.NumericalSystem.TextMode) ==
                        words[j].Text.Simplify(client.NumericalSystem.TextMode)
                       )
                    {
                        str.AppendLine
                        (
                            ++count + "\t" +
                            words[i].Text + "\t" +
                            words[j].Text + "\t" +
                            words[i].Verse.Number + "\t" +
                            words[i].Verse.Chapter.SortedNumber + "\t" +
                            words[i].Verse.NumberInChapter + "\t" +
                            words[i].NumberInVerse + "\t" +
                            words[j].NumberInVerse + "\t" +
                            words[i].Verse.Text
                        );
                    }
                }
            }
        }
        return str.ToString();
    }
