    private static string DoRepeatedPhrases(Client client, List<Verse> verses, string param)
    {
        if (client == null)
            return null;
        if (client.NumericalSystem == null)
            return null;
        if (verses == null)
            return null;
        if (param == null)
            return null;

        int gap = 0;
        if (int.TryParse(param, out gap))
        { }
        StringBuilder str = new StringBuilder();
        if (verses.Count > 0)
        {
            int count = 0;
            //for (int n = 1; n <= 128 / 2; n++) // max words per verse = 128
            for (int n = 1; n <= 10; n++)
            {
                foreach (Verse verse in verses)
                {
                    List<Word> words = verse.Words;
                    for (int i = 0; i <= words.Count - (gap + (2 * n)); i++)
                    {
                        bool found = true;
                        for (int shift = 0; shift < (gap + n); shift++)
                        {
                            if (words[i + shift].Text.Simplify(client.NumericalSystem.TextMode) !=
                                words[i + shift + (gap + n)].Text.Simplify(client.NumericalSystem.TextMode)
                               )
                            {
                                found = false;
                                break;
                            }
                        }
                        if (found)
                        {
                            str.Append(++count + "\t");
                            for (int j = i; j < (i + (gap + (2 * n))); j++)
                            {
                                str.Append(words[j + gap].Text + " ");
                            }
                            str.Remove(str.Length - 1, 1);
                            str.AppendLine("\t" + words[i].Verse.Text);
                        }
                    }
                }
            }
        }
        return str.ToString();
    }
