    private static string DoRepeatedPhrasesAcrossVerses(Client client, List<Verse> verses, string param)
    {
        if (client == null)
            return null;
        if (client.NumericalSystem == null)
            return null;
        if (verses == null)
            return null;
        if (param == null)
            return null;

        int gap = 0;
        if (int.TryParse(param, out gap))
        { }
        StringBuilder str = new StringBuilder();
        if (verses.Count > 0)
        {
            List<Word> words = new List<Word>();
            foreach (Verse verse in verses)
            {
                words.AddRange(verse.Words);
            }

            int count = 0;
            //for (int n = 1; n <= words.Count / 2; n++)
            for (int n = 1; n <= 19; n++)
            {
                for (int i = 0; i <= words.Count - ((2 * n) + gap); i++)
                {
                    bool found = true;
                    for (int shift = 0; shift < n + gap; shift++)
                    {
                        if (words[i + shift].Text.Simplify(client.NumericalSystem.TextMode) !=
                            words[i + shift + n + gap].Text.Simplify(client.NumericalSystem.TextMode)
                           )
                        {
                            found = false;
                            break;
                        }
                    }
                    if (found)
                    {
                        ++count;
                        str.Append(count + "\t");
                        for (int j = i; j < (i + (2 * n) + gap); j++)
                        {
                            str.Append(words[j + gap].Text + " ");
                        }
                        str.Remove(str.Length - 1, 1);
                        str.AppendLine("\t" + words[i].Verse.Text + "\t" + words[i + gap].Verse.Text);
                    }
                }
            }
        }
        return str.ToString();
    }
