    private static string DoRepeatedWordsInConsecutiveVerses(Client client, List<Verse> verses)
    {
        if (client == null)
            return null;
        if (client.NumericalSystem == null)
            return null;
        if (verses == null)
            return null;

        StringBuilder str = new StringBuilder();
        if (verses.Count > 0)
        {
            str.AppendLine
            (
                "N" + "\t" +
                "n" + "\t" +
                "Address" + "\t" +
                "Word" + "\t" +
                "V#" + "\t" +
                "C" + "\t" +
                "V" + "\t" +
                "W" + "\t" +
                "Verse"
            );

            List<Chapter> chapters = client.Book.GetChapters(verses);
            int count = 0;
            int sub_count = 0;
            foreach (Chapter chapter in chapters)
            {
                List<Word> words = new List<Word>();
                foreach (Verse verse in chapter.Verses)
                {
                    words.AddRange(verse.Words);
                }
                bool[] tested_words = new bool[words.Count]; // all are set to false by default

                bool found_in_verse = false;
                for (int i = 0; i < words.Count - 1; i++)
                {
                    if (tested_words[i])
                        continue; // skip processed words before as tested_words[j]
                    tested_words[i] = true;

                    int verse_number = 0;
                    bool word_i_printed = false;
                    for (int j = i + 1; j < words.Count; j++)
                    {
                        // check if consecutive verses condition was broken
                        // if new verse is starting and previous verse ended without finding a match 
                        if ((words[j].NumberInVerse == 1) && (words[j].Verse.Number - verse_number == 1) && (!found_in_verse))
                        {
                            break;
                        }

                        // if new verse is starting
                        if (words[j].NumberInVerse == 1)
                        {
                            verse_number = words[j].Verse.Number;
                            found_in_verse = false;
                        }

                        if (words[i].Text.Simplify(client.NumericalSystem.TextMode) ==
                            words[j].Text.Simplify(client.NumericalSystem.TextMode)
                           )
                        {
                            tested_words[j] = true;
                            found_in_verse = true;

                            if (!word_i_printed)
                            {
                                ++count;
                                sub_count = 1;

                                str.AppendLine
                                (
                                    count + "\t" +
                                    sub_count + "\t" +
                                    words[i].Address + "\t" +
                                    words[i].Text + "\t" +
                                    words[i].Verse.Number + "\t" +
                                    words[i].Verse.Chapter.SortedNumber + "\t" +
                                    words[i].Verse.NumberInChapter + "\t" +
                                    words[i].NumberInVerse + "\t" +
                                    words[i].Verse.Text
                                );
                                word_i_printed = true;
                            }

                            ++sub_count;
                            str.AppendLine
                            (
                                count + "\t" +
                                sub_count + "\t" +
                                words[j].Address + "\t" +
                                words[j].Text + "\t" +
                                words[j].Verse.Number + "\t" +
                                words[j].Verse.Chapter.SortedNumber + "\t" +
                                words[j].Verse.NumberInChapter + "\t" +
                                words[j].NumberInVerse + "\t" +
                                words[j].Verse.Text
                            );
                        }
                    }
                }
            }
        }
        return str.ToString();
    }
