    private static string DoChapterValues(Client client, List<Chapter> chapters)
    {
        if (client == null)
            return null;
        if (chapters == null)
            return null;

        StringBuilder str = new StringBuilder();
        str.Append("#" + "\t" + "Number" + "\t" + "Name" + "\t");
        foreach (string key in client.LoadedNumericalSystems.Keys)
        {
            if (key.StartsWith(client.NumericalSystem.TextMode))
            {
                str.Append(key.Substring(client.NumericalSystem.TextMode.Length + 1) + "\t");
            }
        }
        if (str.Length > 1)
        {
            str.Remove(str.Length - 1, 1); // \t
        }
        str.AppendLine();

        int count = 0;
        foreach (Chapter chapter in chapters)
        {
            str.Append((++count).ToString() + "\t");
            str.Append(chapter.SortedNumber + "\t");
            str.Append(chapter.Name + "\t");
            foreach (NumericalSystem ns in client.LoadedNumericalSystems.Values)
            {
                if (ns != null)
                {
                    if (ns.TextMode == client.NumericalSystem.TextMode)
                    {
                        long value = ns.CalculateValue(chapter.Text);
                        str.Append(value.ToString() + "\t");
                    }
                }
            }
            if (str.Length > 1)
            {
                str.Remove(str.Length - 1, 1);
            }
            str.AppendLine();
        }
        str.AppendLine();

        string duplicates = GetDuplicateChapterValues(client, chapters);
        if (duplicates.Length > 0)
        {
            str.AppendLine(duplicates);
        }
        else
        {
            str.AppendLine("No duplicate values");
        }

        if (str.Length > 2)
        {
            str.Remove(str.Length - 2, 2);
        }

        return str.ToString();
    }
