    private static void DoDoCalculateGaps(long[] numbers, ref StringBuilder str)
    {
        if (numbers == null) return;
        if (numbers.Length <= 1) return;

        str.Append("\t" + "|" + "\t");
        long[] gaps = new long[numbers.Length - 1];
        for (int i = 0; i < numbers.Length - 1; i++)
        {
            gaps[i] = numbers[i + 1] - numbers[i];
            str.Append(gaps[i].ToString() + "\t");
        }
        str.Remove(str.Length - 1, 1);

        DoDoCalculateGaps(gaps, ref str);
    }
    private static long DoDoCalculateFinalGap(long[] numbers)
    {
        if (numbers == null) return -1L;
        if (numbers.Length < 1) return -1L;
        if (numbers.Length == 1) return numbers[0];

        long[] gaps = new long[numbers.Length - 1];
        for (int i = 0; i < numbers.Length - 1; i++)
        {
            gaps[i] = numbers[i + 1] - numbers[i];
        }

        return DoDoCalculateFinalGap(gaps);
    }
    private static void DoDoCalculateAbsGaps(long[] numbers, ref StringBuilder str)
    {
        if (numbers == null) return;
        if (numbers.Length <= 1) return;

        str.Append("\t" + "|" + "\t");
        long[] gaps = new long[numbers.Length - 1];
        for (int i = 0; i < numbers.Length - 1; i++)
        {
            gaps[i] = Math.Abs(numbers[i + 1] - numbers[i]);
            str.Append(gaps[i].ToString() + "\t");
        }
        str.Remove(str.Length - 1, 1);

        DoDoCalculateAbsGaps(gaps, ref str);
    }
    private static long DoDoCalculateAbsFinalGap(long[] numbers)
    {
        if (numbers == null) return -1L;
        if (numbers.Length < 1) return -1L;
        if (numbers.Length == 1) return numbers[0];

        long[] gaps = new long[numbers.Length - 1];
        for (int i = 0; i < numbers.Length - 1; i++)
        {
            gaps[i] = Math.Abs(numbers[i + 1] - numbers[i]);
        }

        return DoDoCalculateAbsFinalGap(gaps);
    }

