    private static void DoPlayWAVFile(string path, List<long> result, string param)
    {
        int sample_rate = 0;
        if (param.Length > 0)
        {
            if (int.TryParse(param, out sample_rate))
            {
                if (sample_rate > 0)
                {
                    // update ref filepath.csv to .wav
                    WAVFile.GenerateWAVFile(ref path, result, sample_rate);

                    // play .wav file
                    WAVFile.PlayWAVFile(path);
                }
            }
            else
            {
                throw new Exception("Invalid sample_rate = " + param);
            }
        }
    }

