    private static string DoSameLettersAtPositionsInWord(Client client, List<Word> words, string param)
    {
        if (client == null)
            return null;
        if (words == null)
            return null;
        if (param == null)
            return null;

        StringBuilder str = new StringBuilder();
        if (!String.IsNullOrEmpty(param))
        {
            str.Append(
                "#" + "\t" +
                "C1" + "\t" +
                "V1" + "\t" +
                "W1" + "\t" +
                "L1" + "\t" +
                "C2" + "\t" +
                "V2" + "\t" +
                "W2" + "\t" +
                "L2" + "\t" +
                "Letter1" + "\t" +
                "Letter2" + "\t" +
                "Word" + "\t" +
                "Verse");
            str.AppendLine();

            int number1 = 0;
            int number2 = 0;
            string[] parts = param.Split(',');
            if (parts.Length == 2)
            {
                if (!int.TryParse(parts[0], out number1))
                    return null;
                if (!int.TryParse(parts[1], out number2))
                    return null;
            }
            int i = number1 - 1;
            int j = number2 - 1;
            if (i < 0)
                return null;
            if (j < 0)
                return null;
            if (i >= j)
                return null;

            long count_sum = 0;
            long c1_sum = 0;
            long v1_sum = 0;
            long w1_sum = 0;
            long l1_sum = 0;
            long c2_sum = 0;
            long v2_sum = 0;
            long w2_sum = 0;
            long l2_sum = 0;

            int count = 0;
            foreach (Word word in words)
            {
                List<Letter> letters = word.Letters;
                if (letters.Count > j)
                {
                    if (letters[i].Text == letters[j].Text)
                    {
                        ++count;
                        str.Append(count.ToString() + "\t");
                        str.Append(letters[i].Word.Verse.Chapter.SortedNumber + "\t");
                        str.Append(letters[i].Word.Verse.NumberInChapter + "\t");
                        str.Append(letters[i].Word.NumberInVerse + "\t");
                        str.Append(letters[i].NumberInWord + "\t");
                        str.Append(letters[j].Word.Verse.Chapter.SortedNumber + "\t");
