                        str.Append(letters[j].Word.NumberInVerse + "\t");
                        str.Append(letters[j].NumberInWord + "\t");
                        str.Append(letters[i].Text + "\t");
                        str.Append(letters[j].Text + "\t");
                        str.Append(word.Text + "\t");
                        str.Append(word.Verse.Text + "\t");
                        str.AppendLine();

                        count_sum += count;
                        c1_sum += letters[i].Word.Verse.Chapter.SortedNumber;
                        v1_sum += letters[i].Word.Verse.NumberInChapter;
                        w1_sum += letters[i].Word.NumberInVerse;
                        l1_sum += letters[i].NumberInWord;
                        c2_sum += letters[j].Word.Verse.Chapter.SortedNumber;
                        v2_sum += letters[j].Word.Verse.NumberInChapter;
                        w2_sum += letters[j].Word.NumberInVerse;
                        l2_sum += letters[j].NumberInWord;
                    }
                }
            }
            str.AppendLine();

            str.AppendLine(
                            count_sum.ToString() + "\t" +
                            c1_sum.ToString() + "\t" +
                            v1_sum.ToString() + "\t" +
                            w1_sum.ToString() + "\t" +
                            l1_sum.ToString() + "\t" +
                            c2_sum.ToString() + "\t" +
                            v2_sum.ToString() + "\t" +
                            w2_sum.ToString() + "\t" +
                            l2_sum.ToString() + "\t" +
                            "\t" +
                            "\t" +
                            "\t" +
                            ""
                          );
        }
        return str.ToString();
