    private static string DoWordNetworkNodes(Client client, List<Word> words)
    {
        if (client == null)
            return null;
        if (words == null)
            return null;

        StringBuilder str = new StringBuilder();
        if (words.Count > 0)
        {
            str.AppendLine("// Generated by Research.dll | Research.cs | WordNodes");

            str.AppendLine
            (
                //"#" + "\t" +
                "Id" + "\t" +
                "X" + "\t" +
                "Y" + "\t" +
                "Z" + "\t" +
                "Text" + "\t" +
                "Meaning" + "\t" +
                "Root" + "\t" +
                "Value" + "\t" +
                "Verse"
            );

            //int count = 0;
            foreach (Word word in words)
            {
                str.AppendLine
                (
                    //++count + "\t" +
                    word.Number + "\t" +
                    word.Verse.Chapter.SortedNumber + "\t" +
                    word.Verse.NumberInChapter + "\t" +
                    word.NumberInVerse + "\t" +
                    word.Text + "\t" +
                    word.Meaning + "\t" +
                    word.Root + "\t" +
                    client.CalculateValue(word).ToString() + "\t" +
                    word.Verse.Number
                );
            }
        }
        return str.ToString();
    }
