    private static string DoWordNumber_EQ_WordValue(Client client, List<Verse> verses)
    {
        if (client == null)
            return null;
        if (client.Book == null)
            return null;
        if (verses == null)
            return null;
        List<Chapter> chapters = client.Book.GetChapters(verses);

        StringBuilder str = new StringBuilder();
        str.AppendLine("Address" + "\t" + "Text" + "\t" + "Value");
        foreach (Chapter chapter in chapters)
        {
            foreach (Verse verse in chapter.Verses)
            {
                foreach (Word word in verse.Words)
                {
                    long value = client.CalculateValue(word);
                    if (word.NumberInChapter == value)
                    {
                        str.AppendLine(word.Address + "\t" + word.Text + "\t" + value);
                    }
                }
            }
        }
        return str.ToString();
    }
    private static string DoLetterNumber_EQ_WordValue(Client client, List<Verse> verses)
    {
        if (client == null)
            return null;
        if (client.Book == null)
            return null;
        if (verses == null)
            return null;
        List<Chapter> chapters = client.Book.GetChapters(verses);

        StringBuilder str = new StringBuilder();
        str.AppendLine("Address" + "\t" + "Text" + "\t" + "Value");
        foreach (Chapter chapter in chapters)
        {
            foreach (Verse verse in chapter.Verses)
            {
                foreach (Word word in verse.Words)
                {
                    long value = 0L;
                    value += client.CalculateValue(word);
                    if (word.Letters[0].NumberInChapter == value)
                    {
                        str.AppendLine(word.Address + "\t" + word.Text + "\t" + value);
                    }
                }
            }
        }
        return str.ToString();
    }
    private static string DoLetterNumber_EQ_LetterValues(Client client, List<Verse> verses)
    {
        if (client == null)
            return null;
        if (client.Book == null)
            return null;
        if (verses == null)
            return null;
        List<Chapter> chapters = client.Book.GetChapters(verses);

        StringBuilder str = new StringBuilder();
        str.AppendLine("Address" + "\t" + "Text" + "\t" + "Value");
        foreach (Chapter chapter in chapters)
        {
            foreach (Verse verse in chapter.Verses)
            {
                foreach (Word word in verse.Words)
                {
                    long value = 0L;
                    string word_start = null;
                    for (int i = 0; i < word.Letters.Count; i++)
                    {
                        value += client.CalculateValue(word.Letters[i]);
                        word_start += word.Letters[i].Text;
                        if (word.Letters[0].NumberInChapter == value)
                        {
                            if (i == word.Letters.Count - 1) // full word
                            {
                                str.AppendLine(word.Address + "\t" + word_start + "\t" + value);
                            }
                            else // partial word
                            {
                                string word_end = null;
                                for (int j = i + 1; j < word.Letters.Count; j++)
                                {
                                    word_end += word.Letters[j].Text;
                                }
                                str.AppendLine(word.Address + "\t" + word_start + "." + word_end + "\t" + value);
                                break;
                            }
                        }
                    }
                }
            }
        }
        return str.ToString();
    }

