    private static string InitialLetters_EQ_Verses(Client client, string param, bool in_search_result)
    {
        if (client == null)
            return null;

        List<Verse> verses = GetSourceVerses(client, in_search_result);

        StringBuilder str = new StringBuilder();
        if (str != null)
        {
            str.AppendLine("Letters" + "\t" + "Matches" + "\t" + "Chapter" + "\t" + "Number" + "\t" + "Verses");

            if (verses != null)
            {
                List<Chapter> chapters = client.Book.GetChapters(verses);
                if (chapters != null)
                {
                    foreach (Chapter chapter in chapters)
                    {
                        if (chapter.InitializationType == InitializationType.Key)
                            continue;
                        if (chapter.InitializationType == InitializationType.NonInitialized)
                            continue;

                        int chapter_number = chapter.SortedNumber;
                        int chapter_verses = chapter.Verses.Count;

                        Dictionary<char, int> letter_frequencies = new Dictionary<char, int>();
                        foreach (Verse verse in chapter.Verses)
                        {
                            foreach (Word word in verse.Words)
                            {
                                string word_text = word.Text.Simplify29();
                                foreach (char c in word_text)
                                {
                                    if (!letter_frequencies.ContainsKey(c))
                                    {
                                        letter_frequencies.Add(c, 1);
                                    }
                                    else
                                    {
                                        letter_frequencies[c]++;
                                    }
                                }
                            }
                        }

                        Word initial_word = client.Book.WithBismAllah ? chapter.Verses[0].Words[4] : chapter.Verses[0].Words[0];
                        if (initial_word != null)
                        {
                            string initial_word_text = initial_word.Text.Simplify29();
                            foreach (char c in initial_word_text)
                            {
                                if ((letter_frequencies[c] == chapter_number) || (letter_frequencies[c] == chapter_verses))
                                {
                                    str.AppendLine(c.ToString() + "\t" + letter_frequencies[c].ToString() + "\t" + chapter.Name + "\t" + chapter.SortedNumber.ToString() + "\t" + chapter.Verses.Count.ToString());
                                }
                            }
                        }
                    }
                }
            }
        }

        return str.ToString();
    }
