            str.AppendLine("Letters" + "\t" + "Matches" + "\t" + "Chapter" + "\t" + "Verses");

            if (verses != null)
            {
                List<Chapter> chapters = client.Book.GetChapters(verses);
                if (chapters != null)
                {
                    foreach (Chapter chapter in chapters)
                    {
                        Dictionary<char, int> letter_frequencies = new Dictionary<char, int>();
                        foreach (Verse verse in chapter.Verses)
                        {
                            foreach (Word word in verse.Words)
                            {
                                foreach (Letter letter in word.Letters)
                                {
                                    if (!letter_frequencies.ContainsKey(letter.Character))
                                    {
                                        letter_frequencies.Add(letter.Character, 1);
                                    }
                                    else
                                    {
                                        letter_frequencies[letter.Character]++;
                                    }
                                }
                            }
                        }

                        foreach (char key in letter_frequencies.Keys)
                        {
                            if (letter_frequencies[key] == chapter.Verses.Count)
                            {
                                str.AppendLine(key + "\t" + letter_frequencies[key].ToString() + "\t" + chapter.Name + "\t" + chapter.Verses.Count.ToString());
                            }
                        }
                    }
                }
            }
        }

        return str.ToString();
    }
