    private static string DoVersePvc(Client client, List<int> numbers, List<Verse> verses)
    {
        if (client == null)
            return null;
        if (verses == null)
            return null;

        StringBuilder str = new StringBuilder();
        str.AppendLine("C" + "\t" + "V" + "\t" +
                       "VC" + "\t" + "Pvc" + "\t" + "Pvc+VC" + "\t" + "Pvc-VC" + "\t" +
                       "Text"
                      );

        foreach (Verse verse in verses)
        {
            int C = verse.Chapter.SortedNumber;
            int V = verse.NumberInChapter;
            int VC = int.Parse(V + "" + C);
            if (VC >= Numbers.Primes.Count)
                continue;
            long Pvc = Numbers.Primes[VC - 1];
            long sum = Pvc + VC;
            long diff = Pvc - VC;

            foreach (long number in numbers)
            {
                if ((sum == number) || (diff == number))
                {
                    str.Append(C.ToString() + "\t");
                    str.Append(V.ToString() + "\t");
                    str.Append(VC.ToString() + "\t");
                    str.Append(Pvc.ToString() + "\t");
                    str.Append(sum.ToString() + "\t");
                    str.Append(diff.ToString() + "\t");
                    str.Append(verse.Text);
                    str.AppendLine();
                }
            }
        }

        return str.ToString();
    }
