    private static string DoFirstWordFrequency_EQ_VerseNumber(Client client, List<Verse> verses)
    {
        if (client == null)
            return null;
        if (verses == null)
            return null;

        StringBuilder str = new StringBuilder();
        if (verses.Count > 0)
        {
            str.AppendLine
            (
                "#" + "\t" +
                "Word" + "\t" +
                "Text" + "\t" +
                "Frequency"
            );

            int count = 0;
            foreach (Verse verse in verses)
            {
                Word word = verse.Words[0];
                if (word != null)
                {
                    int frequency = 0;
                    foreach (Verse v in verses)
                    {
                        foreach (Word w in v.Words)
                        {
                            if (word.Text == w.Text)
                            {
                                frequency++;
                            }
                        }
                    }

                    if (frequency == verse.NumberInChapter)
                    {
                        str.AppendLine
                        (
                            (++count).ToString() + "\t" +
                            word.Address + "\t" +
                            word.Text + "\t" +
                            frequency.ToString()
                        );
                    }
                }
            }
        }
        return str.ToString();
    }
