        {
            long p = Numbers.PrimeIndexOf(n) + 1;
            if (p > 0)
            {
                str.AppendLine(++count + "\t" + n + "\t" + p);
            }
        }

        return str.ToString();
    }
    private static string P_AP_Squares(Client client, string param, bool in_search_result)
    {
        if (client == null)
            return null;

        StringBuilder str = new StringBuilder();
        str.AppendLine("#" + "\t" + "Number" + "\t" + "P" + "\t" + "AP" + "\t" + "XP");

        int count = 0;
        foreach (long n in Numbers.P_AP_Squares)
        {
            long p = Numbers.PrimeIndexOf(n) + 1;
            if (p > 0)
            {
                long ap = Numbers.AdditivePrimeIndexOf(n) + 1;
                if (ap > 0)
                {
                    str.AppendLine(++count + "\t" +
                            n + "\t" +
                            p + "\t" +
                            ap + "\t" +
                            "-"
                          );
                }
            }
        }

        return str.ToString();
    }
    private static string P_XP_Squares(Client client, string param, bool in_search_result)
    {
        if (client == null)
            return null;

        StringBuilder str = new StringBuilder();
        str.AppendLine("#" + "\t" + "Number" + "\t" + "P" + "\t" + "AP" + "\t" + "XP");

        int count = 0;
        foreach (long n in Numbers.P_XP_Squares)
        {
            long p = Numbers.PrimeIndexOf(n) + 1;
            if (p > 0)
            {
                long xp = Numbers.NonAdditivePrimeIndexOf(n) + 1;
                if (xp > 0)
                {
                    str.AppendLine(++count + "\t" +
                            n + "\t" +
                            p + "\t" +
                            "-" + "\t" +
                            xp
                          );
                }
            }
        }

        return str.ToString();
    }
    private static string C_Squares(Client client, string param, bool in_search_result)
