    // Across Chapters - PC
    private static string PC_MatchVerses(Client client, string param, bool in_search_result)
    {
        if (client.Book == null)
            return null;
        if (client.NumericalSystem == null)
            return null;
        List<Verse> verses = GetSourceVerses(client, in_search_result);
        List<Chapter> chapters = client.Book.GetChapters(verses);

        StringBuilder str = new StringBuilder();
        if (!String.IsNullOrEmpty(param))
        {
            string[] parts = param.Split(',');
            if (parts.Length > 0)
            {
                List<int> indices = new List<int>();
                foreach (string part in parts)
                {
                    int number;
                    if (int.TryParse(part, out number))
                    {
                        indices.Add(number);
                    }
                }

                try
                {
                    List<long> primes = new List<long>();
                    List<long> composites = new List<long>();
                    foreach (int n in indices)
                    {
                        primes.Add(Numbers.Primes[n - 1]);
                        composites.Add(Numbers.Composites[n - 1]);
                    }

                    str.AppendLine("#" + "\t" + "Chapter" + "\t" + "Name" + "\t" + "Verses" + "\t" + "Sum" + "\t" + "Words" + "\t" + "Letters");

                    int count = 0;
                    for (int i = 0; i < chapters.Count; i++)
                    {
                        for (int j = 0; j < chapters.Count; j++)
                        {
                            if
                            (
                                (chapters[i].Verses.Count >= primes[primes.Count - 1])
                                &&
                                (chapters[j].Verses.Count >= primes[primes.Count - 1])
                                &&
                                (chapters[i].Verses.Count >= composites[composites.Count - 1])
                                &&
                                (chapters[j].Verses.Count >= composites[composites.Count - 1])
                            )
                            {
                                int primes_sum = 0;
                                int prime_word_count = 0;
                                int prime_letter_count = 0;
                                string primes_str = "";
                                foreach (long p in primes)
                                {
                                    primes_sum += (int)p;
                                    prime_word_count += chapters[i].Verses[(int)p - 1].Words.Count;
                                    prime_letter_count += chapters[i].Verses[(int)p - 1].Letters.Count;
                                    primes_str += p.ToString() + ",";
                                }
                                primes_str = primes_str.Remove(primes_str.Length - 1);

                                int composites_sum = 0;
                                int composite_word_count = 0;
                                int composite_letter_count = 0;
                                string composites_str = "";
                                foreach (long c in composites)
                                {
                                    composites_sum += (int)c;
                                    composite_word_count += chapters[j].Verses[(int)c - 1].Words.Count;
                                    composite_letter_count += chapters[j].Verses[(int)c - 1].Letters.Count;
                                    composites_str += c.ToString() + ",";
                                }
                                composites_str = composites_str.Remove(composites_str.Length - 1);

                                if (
                                    (prime_word_count == composite_word_count)
                                    &&
                                    (prime_letter_count == composite_letter_count))
                                {
                                    str.AppendLine(
                                        (++count).ToString() + "\t" +
                                        chapters[i].SortedNumber + "\t" + chapters[i].Name + "\t" +
                                        primes_str + "\t" + primes_sum + "\t" + prime_word_count + "\t" + prime_letter_count + "\r\n" +
                                        "\t" +
                                        chapters[j].SortedNumber + "\t" + chapters[j].Name + "\t" +
                                        composites_str + "\t" + composites_sum + "\t" + composite_word_count + "\t" + composite_letter_count);
                                    str.AppendLine();
                                }
                            }
                        }
                    }
                }
                catch
                {
                    // skip chapters with fewer verses than indices
                }
            }
        }

        return str.ToString();
    }
