    private static string DoAllVerses_PVC(Client client, List<Verse> verses)
    {
        StringBuilder str = new StringBuilder();
        if (verses != null)
        {
            if (verses.Count > 0)
            {
                str.AppendLine
                    (
                        "#" + "\t" +
                        "Chapter" + "\t" +
                        "Verse" + "\t" +
                        "VC" + "\t" +
                        "P" + "\t" +
                        "P+VC" + "\t" +
                        "P-VC" + "\t" +
                        "Text"
                      );

                int count = 0;
                foreach (Verse verse in verses)
                {
                    int C = verse.Chapter.SortedNumber;
                    int V = verse.NumberInChapter;
                    string xxx = V.ToString() + C.ToString();
                    int VC = int.Parse(xxx);
                    long P = Numbers.Primes[VC - 1];
                    str.AppendLine(
                        ++count + "\t" +
                        C.ToString() + "\t" +
                        V.ToString() + "\t" +
                        VC.ToString() + "\t" +
                        P.ToString() + "\t" +
                        (P + VC).ToString() + "\t" +
                        (P - VC).ToString() + "\t" +
                        verse.Text
                      );
                }
            }
        }
        return str.ToString();
    }
