    private static string DoP_PivotVersesWithText(Client client, List<Verse> verses, string param)
    {
        if (client == null)
            return null;
        if (verses == null)
            return null;
        if (param == null)
            return null;

        StringBuilder str = new StringBuilder();
        str.Append("Pivot" + "\t" + "M" + "\t" + "N" + "\t" + "M*N" + "\t" + "P" + "\t" + "MN+P" + "\t" + "Text" + "\r\n");

        for (int i = 1; i <= 114; i++)
        {
            int M = 1;
            int N = (i * 2) - 1;

            do
            {
                long MN = M * N;
                long P = Numbers.Primes[M - 1];
                long MN_P = MN + P;

                string verse_text = GetVersesWithText(client, MN_P, param);
                str.Append(i + "\t" + M + "\t" + N + "\t" + MN + "\t" + P + "\t" + MN_P + "\t" + verse_text + "\r\n");

                M++;
                N--;
            } while (N > 0);

            str.AppendLine();
            str.AppendLine();
        }
        return str.ToString();
    }
