    private static string GetVersesWithText(Client client, long value, string text)
    {
        if (client == null)
            return null;
        if (client.Book == null)
            return null;
        if (client.Book.Verses == null)
            return null;

        StringBuilder str = new StringBuilder();
        foreach (Verse verse in client.Book.Verses)
        {
            long verse_value = client.CalculateValue(verse);
            if (verse_value == value)
            {
                if (verse.Text.Contains(text))
                {
                    str.Append(verse.Address + "\t" + verse.Text + "\t");
                }
            }
        }
        if (str.Length > 0)
        {
            str.Remove(str.Length - 1, 1); // remove last "\t"
        }
        return str.ToString();
    }

