    private static string GetConsecutiveVerses(Client client, long target1, long target2, bool display_both)
    {
        if (client == null)
            return null;
        if (client.Book == null)
            return null;
        if (client.Book.Verses == null)
            return null;

        StringBuilder str = new StringBuilder();
        if ((target1 > 0) && (target2 > 0))
        {
            List<Verse> found_verses1 = new List<Verse>();
            List<Verse> found_verses2 = new List<Verse>();
            foreach (Verse verse in client.Book.Verses)
            {
                long value = client.CalculateValue(verse);
                if (target1 == value)
                {
                    found_verses1.Add(verse);
                }
                if (target2 == value)
                {
                    found_verses2.Add(verse);
                }
            }

            foreach (Verse verse1 in found_verses1)
            {
                foreach (Verse verse2 in found_verses2)
                {
                    if (Math.Abs(verse2.Number - verse1.Number) == 1) // consecutive verses
                    {
                        if (display_both)
                        {
                            str.Append(verse1.Text + "\t" + verse2.Text + "\t");
                        }
                        else
                        {
                            str.Append(verse1.Text + "\t");
                        }
                    }
                }
            }
        }
        return str.ToString();
    }

