    private static string VerseRanges_WsLs_EQ_CV(Client client, string param, bool in_search_result)
    {
        if (client == null) return null;
        if (client.Book == null) return null;

        StringBuilder str = new StringBuilder();

        str.AppendLine
        (
            "#" + "\t" +
            "Verses" + "\t" +
            "Words" + "\t" +
            "Sum" + "\t" +
            "Letters" + "\t" +
            "Sum" + "\t" +
            "Name" + "\t" +
            "Chapter" + "\t" +
            "Verses" + "\t" +
            "Texts"
        );

        int size;
        if (int.TryParse(param, out size))
        {
            int count = 0;
            int total_verses = client.Book.Verses.Count;
            for (int i = 0; i < total_verses - size; i++)
            {
                int word_count = 0;
                int letter_count = 0;
                string word_count_text = "";
                string letter_count_text = "";
                string verse_numbers_text = "";
                string verse_texts = "";
                for (int j = 0; j < size; j++)
                {
                    int w_count = client.Book.Verses[i + j].Words.Count;
                    int l_count = client.Book.Verses[i + j].Letters.Count;
                    string verse_text = client.Book.Verses[i + j].Text;

                    word_count += w_count;
                    word_count_text += w_count.ToString() + "+";
                    letter_count += l_count;
                    letter_count_text += l_count.ToString() + "+";
                    verse_numbers_text += (i + j + 1).ToString() + ",";
                    verse_texts += verse_text + "\t";
                }
                if (word_count_text.Length > 0) word_count_text = word_count_text.Remove(word_count_text.Length - 1);
                if (letter_count_text.Length > 0) letter_count_text = letter_count_text.Remove(letter_count_text.Length - 1);
                if (verse_numbers_text.Length > 0) verse_numbers_text = verse_numbers_text.Remove(verse_numbers_text.Length - 1);

                foreach (Chapter chapter in client.Book.Chapters)
                {
                    if ((word_count == chapter.SortedNumber) && (letter_count == chapter.Verses.Count))
                    {
                        str.AppendLine
                        (
                            ++count + "\t" +
                            verse_numbers_text + "\t" +
                            word_count_text + "\t" +
                            word_count + "\t" +
                            letter_count_text + "\t" +
                            letter_count + "\t" +
                            chapter.Name + "\t" +
                            chapter.SortedNumber + "\t" +
                            chapter.Verses.Count + "\t" +
                            verse_texts
                        );
                    }
                }
            }
        }
        return str.ToString();
    }
