        StringBuilder str = new StringBuilder();

        int size;
        if (int.TryParse(param, out size))
        {
            int index = 2;
            int total_verses = client.Book.Verses.Count;
            int constant = total_verses + 1;
            for (int i = total_verses - 2; i > size; i -= size)
            {
                str.AppendLine
                (
                    "#" + "\t" +
                    "Total" + "\t" +
                    "P" + "\t" +
                    "Total-P" + "\t" +
                    "Chapter" + "\t" +
                    "Verse" + "\t" +
                    "Text"
                );

                bool stop = false;
                int verse_count_sum = 0;
                int word_count_sum = 0;
                int letter_count_sum = 0;
                Chapter old_chapter = null;
                int chapter_number_sum = 0;
                int verse_number_sum = 0;
                int word_number_sum = 0;
                int letter_number_sum = 0;
                StringBuilder csv = new StringBuilder();
                for (int j = 0; j < size; j++)
                {
                    int P = (int)Numbers.Primes[index++];
                    if (P >= constant)
                    {
                        stop = true;
                        break;
                    }

                    int diff = constant - P;
                    csv.Append(diff + ",");
                    Verse verse = client.Book.Verses[diff - 1];
                    if (verse != null)
                    {
                        str.AppendLine
                        (
                            (i - j) + "\t" +
                            constant + "\t" +
                            P + "\t" +
                            diff + "\t" +
                            verse.Chapter.Name + "\t" +
                            verse.Chapter.SortedNumber + "\t" +
                            verse.NumberInChapter + "\t" +
                            verse.Text
                        );

                        verse_count_sum++;
                        word_count_sum += verse.Words.Count;
                        letter_count_sum += verse.Letters.Count;

                        Chapter chapter = verse.Chapter;
                        if (old_chapter != chapter)
                        {
                            old_chapter = chapter;
                            chapter_number_sum += verse.Chapter.SortedNumber;
                        }
                        verse_number_sum += verse.NumberInChapter;
                        foreach (Word word in verse.Words)
                        {
                            word_number_sum += word.NumberInVerse;
                        }
                        foreach (Letter letter in verse.Letters)
                        {
                            letter_number_sum += letter.NumberInWord;
                        }
                    }
                }
                if (csv.Length > 0) csv.Remove(csv.Length - 1, 1);

                int count = (constant / size) - ((i + 1) / size) + 1;
                str.AppendLine("------------------------------------------------------------");
                str.AppendLine(count + "\t" + "Verses" + "\t" + "Words" + "\t" + "Letters" + "\t" + "CSum" + "\t" + "VSum" + "\t" + "WSum" + "\t" + "LSum" + "\t" + "VerseNumbers");
                str.AppendLine("------------------------------------------------------------");
