    private static string DoChapterFactorsSum_EQ_Verses(Client client, List<Chapter> chapters)
    {
        if (client == null)
            return null;
        if (chapters == null)
            return null;

        StringBuilder str = new StringBuilder();
        str.AppendLine(
            "Name" + "\t" +
            "Chapter" + "\t" +
            "Factors" + "\t" +
            "Sum" + "\t" +
            "Verses"
            );

        foreach (Chapter chapter in chapters)
        {
            int chapter_number = chapter.SortedNumber;
            long sum = 0L;
            List<long> chapter_number_factors = Numbers.Factorize(chapter_number);
            foreach (long factor in chapter_number_factors)
            {
                sum += factor;
            }

            int chapter_verses = chapter.Verses.Count;

            if (sum == chapter_verses)
            {
                str.AppendLine(
                    chapter.Name + "\t" +
                    chapter_number.ToString() + "\t" +
