    private static string DoVersesFactorsSum_EQ_Chapter(Client client, List<Chapter> chapters)
    {
        if (client == null)
            return null;
        if (chapters == null)
            return null;

        StringBuilder str = new StringBuilder();
        str.AppendLine(
            "Name" + "\t" +
            "Chapter" + "\t" +
            "Verses" + "\t" +
            "Factors" + "\t" +
            "Sum"
            );

        foreach (Chapter chapter in chapters)
        {
            int chapter_number = chapter.SortedNumber;

            int chapter_verses = chapter.Verses.Count;
            long sum = 0L;
            List<long> chapter_verses_factors = Numbers.Factorize(chapter_verses);
            foreach (long factor in chapter_verses_factors)
            {
                sum += factor;
            }

            if (sum == chapter_number)
            {
                str.AppendLine(
                    chapter.Name + "\t" +
                    chapter_number.ToString() + "\t" +
                    chapter_verses.ToString() + "\t" +
                    Numbers.FactorizeToString(chapter_verses) + "\t" +
                    sum.ToString()
                );
            }
        }
        return str.ToString();
    }
