            return null;
        if (client.Book.Chapters == null)
            return null;
        if (client.Book.Chapters.Count <= 0)
            return null;
        if (client.Book.Chapters[0].Verses == null)
            return null;
        if (client.Book.Chapters[0].Verses.Count <= 0)
            return null;
        if (client.NumericalSystem == null)
            return null;

        NumericalSystem backup_numerical_system = new NumericalSystem(client.NumericalSystem);

        long target_difference;
        try
        {
            target_difference = long.Parse(param);
        }
        catch
        {
            target_difference = 0L;
        }

        // zero difference between Value(BismAllah) and ValueIndex(AlFatiha)
        List<ZeroDifferenceNumericalSystem> good_numerical_systems = new List<ZeroDifferenceNumericalSystem>();

        NumberType[] number_types = (NumberType[])Enum.GetValues(typeof(NumberType));
        foreach (NumberType number_type in number_types)
        {
            if (
                (number_type == NumberType.Prime) ||
                (number_type == NumberType.AdditivePrime) ||
                (number_type == NumberType.NonAdditivePrime) ||
                (number_type == NumberType.Composite) ||
                (number_type == NumberType.AdditiveComposite) ||
                (number_type == NumberType.NonAdditiveComposite)
               )
            {
                // Quran 74:30 "Over It Nineteen."
                int PERMUTATIONS = 524288; // 2^19
                for (int i = 0; i < PERMUTATIONS; i++)
                {
                    client.NumericalSystem.AddToLetterLNumber = ((i & 262144) != 0);
                    client.NumericalSystem.AddToLetterWNumber = ((i & 131072) != 0);
                    client.NumericalSystem.AddToLetterVNumber = ((i & 65536) != 0);
                    client.NumericalSystem.AddToLetterCNumber = ((i & 32768) != 0);
                    client.NumericalSystem.AddToLetterLDistance = ((i & 16384) != 0);
                    client.NumericalSystem.AddToLetterWDistance = ((i & 8192) != 0);
                    client.NumericalSystem.AddToLetterVDistance = ((i & 4096) != 0);
                    client.NumericalSystem.AddToLetterCDistance = ((i & 2048) != 0);
                    client.NumericalSystem.AddToWordWNumber = ((i & 1024) != 0);
                    client.NumericalSystem.AddToWordVNumber = ((i & 512) != 0);
                    client.NumericalSystem.AddToWordCNumber = ((i & 256) != 0);
                    client.NumericalSystem.AddToWordWDistance = ((i & 128) != 0);
                    client.NumericalSystem.AddToWordVDistance = ((i & 64) != 0);
                    client.NumericalSystem.AddToWordCDistance = ((i & 32) != 0);
                    client.NumericalSystem.AddToVerseVNumber = ((i & 16) != 0);
                    client.NumericalSystem.AddToVerseCNumber = ((i & 8) != 0);
                    client.NumericalSystem.AddToVerseVDistance = ((i & 4) != 0);
                    client.NumericalSystem.AddToVerseCDistance = ((i & 2) != 0);
                    client.NumericalSystem.AddToChapterCNumber = ((i & 1) != 0);

                    long alfatiha_value = client.CalculateValue(client.Book.Chapters[0]);
                    int alfatiha_value_index = 0;
                    switch (number_type)
                    {
                        case NumberType.Prime:
                            {
                                alfatiha_value_index = Numbers.PrimeIndexOf(alfatiha_value) + 1;
                            }
                            break;
                        case NumberType.AdditivePrime:
                            {
                                alfatiha_value_index = Numbers.AdditivePrimeIndexOf(alfatiha_value) + 1;
                            }
                            break;
                        case NumberType.NonAdditivePrime:
                            {
                                alfatiha_value_index = Numbers.NonAdditivePrimeIndexOf(alfatiha_value) + 1;
                            }
                            break;
                        case NumberType.Composite:
                            {
                                alfatiha_value_index = Numbers.CompositeIndexOf(alfatiha_value) + 1;
                            }
                            break;
                        case NumberType.AdditiveComposite:
                            {
                                alfatiha_value_index = Numbers.AdditiveCompositeIndexOf(alfatiha_value) + 1;
                            }
                            break;
                        case NumberType.NonAdditiveComposite:
                            {
                                alfatiha_value_index = Numbers.NonAdditiveCompositeIndexOf(alfatiha_value) + 1;
                            }
                            break;
                        default:
                            break;
                    }

                    if (alfatiha_value_index > 0)
                    {
                        long bismAllah_value = client.CalculateValue(client.Book.Chapters[0].Verses[0]);

                        long difference = bismAllah_value - (long)alfatiha_value_index;
                        if (Math.Abs(difference) <= target_difference)
                        {
                            ZeroDifferenceNumericalSystem good_numerical_system = new ZeroDifferenceNumericalSystem();
                            if (good_numerical_system != null)
                            {
                                good_numerical_system.NumericalSystem = new NumericalSystem(client.NumericalSystem);
                                good_numerical_system.NumberType = number_type;
                                good_numerical_system.BismAllahValue = bismAllah_value;
                                good_numerical_system.AlFatihaValue = alfatiha_value;
                                good_numerical_system.AlFatihaValueIndex = alfatiha_value_index;
                                good_numerical_systems.Add(good_numerical_system);
                            }
                        }
                    }

                } // next PERMUTATION

                string filename = "BismAllah_EQ_AlFatiha" + number_type.ToString() + "IndexSystem" + ".txt";
                if (Directory.Exists(Globals.RESEARCH_FOLDER))
                {
                    string path = Globals.RESEARCH_FOLDER + Path.DirectorySeparatorChar + filename;

                    StringBuilder str = new StringBuilder();
                    str.AppendLine("TextMode" +
                            "\t" + "LetterOrder" +
                            "\t" + "LetterValues" +
                            "\t" + "AddToLetterLNumber" +
                            "\t" + "AddToLetterWNumber" +
                            "\t" + "AddToLetterVNumber" +
                            "\t" + "AddToLetterCNumber" +
                            "\t" + "AddToLetterLDistance" +
                            "\t" + "AddToLetterWDistance" +
                            "\t" + "AddToLetterVDistance" +
                            "\t" + "AddToLetterCDistance" +
                            "\t" + "AddToWordWNumber" +
                            "\t" + "AddToWordVNumber" +
                            "\t" + "AddToWordCNumber" +
                            "\t" + "AddToWordWDistance" +
                            "\t" + "AddToWordVDistance" +
                            "\t" + "AddToWordCDistance" +
                            "\t" + "AddToVerseVNumber" +
                            "\t" + "AddToVerseCNumber" +
                            "\t" + "AddToVerseVDistance" +
                            "\t" + "AddToVerseCDistance" +
                            "\t" + "AddToChapterCNumber" +
                            "\t" + "BismAllahValue" +
                            "\t" + "AlFatihaIndex"
                        );
                    foreach (ZeroDifferenceNumericalSystem good_numerical_system in good_numerical_systems)
                    {
                        if (good_numerical_system != null)
                        {
                            str.Append(good_numerical_system.NumericalSystem.ToTabbedString());
                            str.Append("\t" + good_numerical_system.BismAllahValue.ToString());
                            str.Append("\t" + good_numerical_system.AlFatihaValueIndex.ToString());
                            str.AppendLine();
                        }
                    }
                    FileHelper.SaveText(path, str.ToString());
                    FileHelper.DisplayFile(path);
                }

                // clear for next NumberType
                good_numerical_systems.Clear();

            } // if NumberType

        } // next NumberType

        client.NumericalSystem = backup_numerical_system;

        return null;
    }
