    private static string SystemsWithWordValue_EQ_Frequency(Client client, string param, bool in_search_result)
    {
        if (client == null)
            return null;
        if (client.LoadedNumericalSystems == null)
            return null;

        StringBuilder str = new StringBuilder();
        str.AppendLine("System" + "\t" + "Word" + "\t" + "Value = Frequency");

        Dictionary<string, int> word_frequencies = GetWordFrequencies();
        foreach (string word in word_frequencies.Keys)
        {
            int frequency = word_frequencies[word];
            foreach (NumericalSystem ns in client.LoadedNumericalSystems.Values)
            {
                if (ns != null)
                {
                    if (ns.Name.EndsWith("Zeros")) continue;

                    long value = ns.CalculateValue(word);
                    if (value == frequency)
                    {
                        str.AppendLine(ns.Name + "\t" + word + "\t" + value);
                    }
                }
            }
        }

        string filename = "SystemsWithWordValue_EQ_Frequency" + ".txt";
        string path = Globals.RESEARCH_FOLDER + Path.DirectorySeparatorChar + filename;
        FileHelper.SaveText(path, str.ToString());
        FileHelper.DisplayFile(path);

        return null;
    }
